insert into public.dp_cases(number, difficulty, fields, disease, canonical_id, answer_id, clues) values
(324,'Easy',array['Pediatrics','Infectious Diseases']::text[],'Measles (Rubeola)','measles-rubeola','measles',array['A 4-year-old boy is brought to the clinic with three days of high fever and fussiness.','His parents describe a hacking cough, a runny nose, and red, watery eyes that are sensitive to light.','The family recently returned from abroad, and the boy''s vaccinations were never completed.','Inside the cheeks, small bluish-white spots on a red background are seen opposite the lower molars.','A blotchy red rash starts at the hairline behind the ears and spreads down over the trunk and limbs.','Serum IgM against the paramyxovirus is positive; he receives vitamin A and supportive care, and the case is reported to public health.']::text[]),
(325,'Medium',array['Cardiology','Vascular Surgery']::text[],'Aortic Dissection','aortic-dissection','aortic-dissection',array['A 62-year-old man is rushed to the emergency department with sudden, severe chest pain that began while lifting a box.','He describes the pain as tearing, reaching its worst at onset and moving to the area between his shoulder blades.','He has long-standing hypertension that he controls poorly and smokes a pack a day.','Blood pressure is 182/96 mmHg in the right arm but only 138/80 mmHg in the left arm.','A chest X-ray shows a widened mediastinum, and a soft early diastolic murmur is heard at the left sternal border.','CT angiography shows an intimal flap in the ascending aorta, and he is taken for emergency surgical repair.']::text[]),
(326,'Hard',array['Neurology','Oncology']::text[],'Lambert-Eaton Myasthenic Syndrome','lambert-eaton-myasthenic-syndrome','lambert-eaton-myasthenic-syndrome',array['A 64-year-old man visits his doctor because climbing stairs and rising from a chair have become harder over several months.','He also notices a dry mouth, constipation, and new erectile dysfunction.','He has a 50 pack-year smoking history and has recently lost weight without trying.','Hip and shoulder muscles are weak and reflexes are reduced, yet after a short burst of exercise both strength and reflexes briefly improve.','Repetitive nerve stimulation at high frequency shows a marked increase in muscle response amplitude.','Antibodies against P/Q-type voltage-gated calcium channels are found, and a chest CT reveals a small cell lung carcinoma.']::text[]),
(327,'Extreme',array['Genetics','Neurology','Metabolism']::text[],'Refsum Disease','refsum-disease','refsum-disease',array['A 24-year-old man sees an eye doctor because he struggles to see at night and keeps bumping into things in dim light.','Over the past year he has also lost his sense of smell and noticed numbness in both feet.','Examination shows dry, scaly skin, shortened fourth toes, and an unsteady gait with absent ankle reflexes.','Fundoscopy reveals retinitis pigmentosa, and a hearing test shows sensorineural hearing loss.','Plasma testing reveals a markedly raised phytanic acid level.','Genetic testing confirms an autosomal recessive PHYH mutation, and he begins a diet free of dairy, ruminant fats, and fatty fish.']::text[]),
(328,'Medium',array['Psychiatry','Emergency Medicine & Toxicology']::text[],'Serotonin Syndrome','serotonin-syndrome','serotonin-syndrome',array['A 34-year-old woman is brought to the emergency department by her partner because she has become restless and confused over the evening.','She is sweating heavily, has diarrhea, and keeps saying she feels shaky and cannot sit still.','She takes sertraline for depression and started tramadol two days ago for back pain.','She has a temperature of 38.9 °C, a heart rate of 128 bpm, and dilated pupils.','The neurological exam shows hyperreflexia and inducible clonus that is most marked in the legs.','Both drugs are stopped and she improves with benzodiazepines, cooling, and cyproheptadine.']::text[]),
(329,'Easy',array['Otolaryngology (ENT)']::text[],'Meniere Disease','meniere-disease','meniere-disease',array['A 45-year-old woman comes to clinic after several sudden attacks of spinning dizziness over the past two months.','Each attack lasts a few hours and leaves her nauseated, so she has to lie still until it passes.','Before each attack, her right ear feels full and blocked.','She hears a low roaring sound in the same ear, which gets louder during attacks.','An audiogram shows low-frequency sensorineural hearing loss in the right ear that varies between visits.','Her symptoms improve on a low-salt diet with a diuretic, and she is given a short-term antiemetic for attacks.']::text[]),
(330,'Easy',array['Neurology']::text[],'Migraine','migraine','migraine',array['A 27-year-old woman visits her doctor about headaches that keep coming back every few weeks.','Each headache builds over an hour, throbs on one side of her head, and lasts most of the day.','During attacks she feels sick, vomits, and has to lie in a dark, quiet room.','About twenty minutes before the pain, she sees zigzag flashing lines that spread across her vision and then fade.','Her mother had similar headaches, and attacks often come around her period or after missed sleep.','Her neurological exam is normal; a triptan at onset ends her attacks, and a headache diary is started.']::text[]),
(331,'Easy',array['Pediatrics','Infectious Diseases','Dermatology']::text[],'Varicella (Chickenpox)','varicella-chickenpox','varicella',array['A 5-year-old girl is brought to the clinic with a mild fever and tiredness for one day.','Her parents say she has been scratching all night and is very grumpy.','Several children in her kindergarten class have been off sick with spots this month.','Itchy red spots appeared first on her chest and back and then spread to her face and scalp.','The spots turn into small clear blisters like dewdrops on a red base, with new crops appearing beside crusted older ones.','She is kept home until all lesions crust over and is given calamine lotion and paracetamol, avoiding aspirin.']::text[]),
(332,'Easy',array['Pediatrics','Infectious Diseases']::text[],'Roseola Infantum (Exanthem Subitum)','roseola-exanthem-subitum','roseola-infantum',array['A 10-month-old baby is brought to the clinic after three days of very high fever.','Despite temperatures near 40 °C, the baby has been feeding and playing fairly normally between fever spikes.','The parents were frightened because the baby had a brief febrile seizure on the second day.','This morning the fever suddenly disappeared.','A few hours later, small pink spots appeared on the trunk and neck that fade when pressed and do not itch.','The rash fades within two days; it is caused by human herpesvirus 6, and only reassurance is needed.']::text[]),
(333,'Easy',array['Infectious Diseases']::text[],'Infectious Mononucleosis','infectious-mononucleosis-ebv','infectious-mononucleosis',array['A 17-year-old student visits the clinic feeling exhausted for over a week.','He has a fever and a very sore throat that makes swallowing painful.','He recently started dating someone new at school.','His tonsils are large with a grey-white coating, and the lymph nodes at the back of his neck are swollen and tender.','His spleen tip can be felt below the left rib cage, and his blood film shows many atypical lymphocytes.','A heterophile antibody (Monospot) test is positive, and he is told to avoid contact sports for several weeks.']::text[]),
(334,'Easy',array['Ophthalmology']::text[],'Cataract','cataract','cataract',array['A 72-year-old man tells his doctor that his eyesight has slowly worsened over the past two years.','He finds reading harder and has stopped driving at night.','He has type 2 diabetes and used steroid inhalers for many years.','He complains that headlights and the sun cause bright glare and halos.','There is no pain or redness, but colours look faded and yellowish to him.','Slit-lamp exam shows a cloudy lens, and he is booked for lens removal with an artificial lens implant.']::text[]),
(335,'Easy',array['Dermatology','Infectious Diseases']::text[],'Tinea Pedis (Athlete''s Foot)','athletes-foot-tinea-pedis','tinea-pedis',array['A 22-year-old university swimmer comes to the clinic about an itchy foot.','The itching is worse at night and after he takes off his trainers.','He uses the shared showers at the pool every day without sandals.','The skin between his fourth and fifth toes is white, soggy, and peeling, with small cracks.','A skin scraping examined with potassium hydroxide shows branching fungal hyphae.','He is treated with a topical antifungal cream and told to keep his feet dry and wear sandals in shared showers.']::text[]),
(336,'Easy',array['Dermatology']::text[],'Acne Vulgaris','acne-vulgaris','acne-vulgaris',array['A 15-year-old boy is brought to the clinic by his mother because he has become shy and avoids school photos.','He says the problem started about a year ago and is worse before exams.','His father had a similar problem as a teenager that left some scars.','His forehead, nose, and chin have many blackheads and whiteheads.','There are also red bumps and pus-filled spots on his cheeks and upper back.','He starts topical benzoyl peroxide with a retinoid, and oral doxycycline is added for the inflamed spots.']::text[]),
(337,'Easy',array['Gastroenterology & Hepatology','Surgery & Trauma']::text[],'Hemorrhoids','hemorrhoids','hemorrhoids',array['A 38-year-old office worker visits his doctor feeling embarrassed about a problem in the bathroom.','He has had constipation for months and often strains on the toilet.','He eats little fibre and sits at his desk most of the day.','He notices bright red blood on the toilet paper and dripping into the bowl after stools, without pain.','He also feels a soft lump at the anus after straining that slips back in on its own.','Anoscopy shows swollen vascular cushions above the dentate line; he is advised more fibre and water, and banding is offered.']::text[]),
(338,'Easy',array['Dermatology','Otolaryngology (ENT)']::text[],'Aphthous Ulcer (Canker Sore)','aphthous-ulcer','recurrent-aphthous-stomatitis',array['A 19-year-old student comes in because eating has become painful.','She says this happens a few times a year, especially during exam weeks.','She has no fever and feels otherwise well.','Inside her lower lip there are two small round sores.','Each sore is shallow with a yellow-grey base and a red halo, and is very tender to touch.','They heal on their own within ten days; she is given a soothing mouthwash and a topical steroid paste.']::text[]),
(339,'Easy',array['Dermatology','Surgery & Trauma']::text[],'Ingrown Toenail','ingrown-toenail','ingrown-toenail',array['A 16-year-old football player comes to the clinic limping.','He says his big toe hurts when he wears his boots and when someone steps on it.','He cuts his nails short and rounds off the corners.','The side of his right big toe is red, swollen, and very tender.','The edge of the nail is digging into the skin fold, with a little pus and overgrown tissue.','The nail edge is removed under local anaesthetic, and he is shown how to cut his nails straight across.']::text[]),
(340,'Easy',array['Dermatology','Pediatrics','Infectious Diseases']::text[],'Molluscum Contagiosum','molluscum-contagiosum','molluscum-contagiosum',array['A 4-year-old boy is brought in because of small bumps on his skin that have been there for two months.','The bumps do not hurt but sometimes itch, and more keep appearing.','His older sister had similar bumps last year, and they share bath time.','On his trunk and armpits there are about fifteen firm, smooth, skin-coloured bumps.','Each bump is pearly and dome-shaped with a small dent in the centre.','It is caused by a poxvirus, the bumps usually clear on their own within months, and the family is reassured.']::text[]),
(341,'Easy',array['Dermatology','Pediatrics']::text[],'Head Lice (Pediculosis Capitis)','head-lice-pediculosis-capitis','pediculosis-capitis',array['A 7-year-old girl is brought to the clinic by her father because she cannot stop scratching her head.','The itch is worst at night and has lasted about three weeks.','A note was sent home from school saying several classmates had the same problem.','There are scratch marks and small red bumps at the back of her neck and behind her ears.','Tiny white specks are firmly stuck to hair shafts close to the scalp and do not brush off like dandruff.','Live insects are seen with a fine-toothed comb, and she is treated with a dimeticone lotion repeated after a week.']::text[]),
(342,'Easy',array['Dermatology','Pediatrics']::text[],'Diaper Dermatitis (Nappy Rash)','diaper-dermatitis','diaper-dermatitis',array['A 9-month-old baby is brought in because she cries during nappy changes.','Her mother has been using a new brand of baby wipes, and the baby had diarrhoea last week.','The baby is feeding well and has no fever.','The skin over her buttocks and outer labia is red, shiny, and sore.','The deep skin folds of the groin are spared, and there are no separate satellite spots.','It settles with frequent changes, nappy-free time, and a zinc oxide barrier cream.']::text[]),
(343,'Easy',array['Pediatrics']::text[],'Infantile Colic','infantile-colic','infantile-colic',array['Tired parents bring their 6-week-old son to the clinic because of long crying spells.','He cries hard for more than three hours a day, mostly in the late afternoon and evening.','The crying started at two weeks of age and happens on most days of the week.','During spells he goes red in the face, clenches his fists, and pulls his legs up to his tummy.','Between spells he feeds well, is gaining weight normally, and his examination is completely normal.','The parents are reassured that it usually stops by three to four months and given soothing tips and support.']::text[]),
(344,'Easy',array['Dermatology','Pediatrics']::text[],'Erythema Toxicum Neonatorum','erythema-toxicum-neonatorum','erythema-toxicum-neonatorum',array['A healthy baby boy born at term two days ago is checked before going home.','His mother noticed a rash this morning and is worried it might be an infection.','He is feeding well, has no fever, and is alert and active.','His chest, back, and thighs have blotchy red patches, some with tiny pale yellow bumps in the middle.','The spots move around, fading in some places and appearing in others within hours, and his palms and soles are spared.','A smear of a bump would show eosinophils; it is harmless and fades within one to two weeks without treatment.']::text[]),
(345,'Easy',array['Dermatology']::text[],'Vitiligo','vitiligo','vitiligo',array['A 26-year-old man comes to the clinic about changes in his skin colour that started a few months ago.','He has no itching or pain, but he feels self-conscious at work.','He has autoimmune thyroid disease, and his aunt has a similar skin condition.','There are sharply outlined, completely white patches around his mouth, eyes, and on the backs of his hands.','Under a Wood''s lamp, the patches glow bright chalk-white.','A potent topical steroid or tacrolimus is started, with narrowband UVB phototherapy offered for wider areas.']::text[]),
(346,'Easy',array['Dermatology','Infectious Diseases']::text[],'Onychomycosis (Fungal Nail Infection)','onychomycosis-fungal-nail-infection','onychomycosis',array['A 58-year-old man asks his doctor about the look of his toenails.','He says the problem has slowly got worse over two years and makes it hard to cut his nails.','He has diabetes and had athlete''s foot several times.','Three of his toenails are thick, crumbly, and yellow-brown.','The nails are lifting from the nail bed, with chalky debris underneath.','Nail clippings show fungal hyphae on microscopy and grow a dermatophyte; he starts oral terbinafine for three months.']::text[]),
(347,'Easy',array['Ophthalmology']::text[],'Chalazion','chalazion','chalazion',array['A 30-year-old woman visits the clinic about a lump on her eyelid.','She noticed it three weeks ago, and it was a little sore at first but now is not painful.','She has rosacea and often has crusty, irritated eyelids.','On her upper eyelid there is a firm, round, pea-sized lump.','The lump sits away from the lid margin, and there is no pus or eyelash at its centre.','It is a blocked meibomian gland; warm compresses and lid massage are advised, with incision if it persists.']::text[]),
(348,'Easy',array['Dermatology']::text[],'Corn (Clavus)','corn-clavus','corn',array['A 50-year-old woman visits her doctor about pain in her foot when walking.','She says it feels like there is a small stone in her shoe.','She wears narrow high-heeled shoes for work every day.','There is a small, hard, yellowish area of thick skin on the top of her fifth toe.','Paring the area shows a hard central core, and normal skin lines continue across it, with no black dots.','It is caused by pressure and friction; it is pared down, and she is advised to wear wider shoes and use padding.']::text[]),
(349,'Easy',array['Pediatrics','Orthopedics & Sports Medicine']::text[],'Nursemaid''s Elbow (Radial Head Subluxation)','nursemaids-elbow','nursemaid-s-elbow',array['A 3-year-old girl is brought to the emergency department because she will not use her left arm.','She was fine an hour ago and did not fall.','Her father says he swung her up by her hands while crossing the street, and she cried straight away.','She holds the arm still at her side with the elbow slightly bent and the palm facing down.','There is no swelling or bruising, but she cries when anyone tries to turn her palm up.','The doctor turns her forearm and bends the elbow with a click, and minutes later she is reaching for toys.']::text[]),
(350,'Easy',array['Pediatrics','Infectious Diseases']::text[],'Scarlet Fever','scarlet-fever','scarlet-fever',array['A 6-year-old boy is brought to the clinic with fever and a sore throat for one day.','He vomited once and complains of a headache and tummy ache.','Two children in his class had a sore throat last week.','His tonsils are red and swollen with white patches, and his tongue is red with large bumps.','A red rash on his neck and chest feels like sandpaper, his cheeks are flushed, and the skin around his mouth is pale.','A rapid strep test is positive for group A Streptococcus, and he starts a 10-day course of penicillin.']::text[]),
(351,'Easy',array['Cardiology','Neurology']::text[],'Vasovagal Syncope','vasovagal-syncope','vasovagal-syncope',array['A 19-year-old student is seen after she passed out at a blood donation centre.','She had been standing in a hot, crowded queue for a long time and skipped breakfast.','She has fainted once before, at the sight of blood during a school first-aid class.','Before falling, she felt hot, sweaty, sick, and her vision went grey.','She was out for less than a minute, woke up fully alert with no confusion, and did not bite her tongue.','Her ECG and examination are normal; she is taught to lie down and cross her legs at early warning signs.']::text[]),
(352,'Easy',array['Rheumatology & Immunology','Emergency Medicine & Toxicology']::text[],'Costochondritis','costochondritis','costochondritis',array['A 25-year-old woman comes to the emergency department frightened by chest pain.','The pain has been there for three days and is sharp, on the left side of her chest.','She recently started a new gym routine with lots of push-ups.','The pain gets worse when she takes a deep breath, twists, or presses on the area.','Pressing on the joints where her second to fourth ribs meet the breastbone reproduces the exact pain, without any swelling.','Her ECG and chest X-ray are normal; it is inflammation of the rib cartilage, and she is given anti-inflammatories and rest.']::text[]),
(353,'Easy',array['Dermatology','Infectious Diseases']::text[],'Herpes Zoster (Shingles)','herpes-zoster','herpes-zoster',array['A 68-year-old man visits his doctor about burning pain on the right side of his chest.','The pain started four days ago and feels like a burn, even under light clothing.','He had chickenpox as a child and has been under a lot of stress lately.','Two days after the pain began, a red rash appeared in the same area.','The rash is a band of grouped blisters wrapping from his spine to the front of his chest, stopping at the midline.','He starts valaciclovir within 72 hours of the rash, and pain relief is arranged; the vaccine is advised once he recovers.']::text[]),
(354,'Easy',array['Infectious Diseases','Dermatology']::text[],'Cellulitis','cellulitis','cellulitis',array['A 55-year-old man comes to the clinic with a painful leg.','He has had a fever and chills since yesterday.','He has diabetes and cracked skin between his toes from athlete''s foot.','His lower leg is red, hot, swollen, and tender.','The red area has a poorly defined edge, and it has spread beyond the pen line drawn this morning.','Ultrasound excludes a clot, and he starts antibiotics against streptococci and staphylococci, such as flucloxacillin.']::text[]),
(355,'Easy',array['Infectious Diseases','Pulmonology']::text[],'Influenza','influenza','influenza',array['A 35-year-old teacher calls in sick in the middle of winter.','He says he felt fine yesterday morning but was suddenly hit by illness in the afternoon.','Many students in his school have been off with something similar this week.','He has a high fever, chills, severe muscle aches, and a pounding headache.','A dry cough and sore throat follow, and he feels too exhausted to get out of bed.','A nasal swab PCR is positive for an orthomyxovirus type A; he rests, drinks fluids, and is told to get the yearly vaccine.']::text[]),
(356,'Easy',array['Endocrinology','Emergency Medicine & Toxicology']::text[],'Hypoglycemia','hypoglycemia','hypoglycemia',array['A 23-year-old man is brought to the emergency department by friends because he is acting strangely.','They say he became confused, irritable, and slurred his words during a football match.','He has type 1 diabetes, took his usual insulin dose, and skipped lunch.','He is pale, shaking, sweating heavily, and his heart is racing.','A finger-prick glucose reading is 2.4 mmol/L (43 mg/dL).','He recovers within minutes after an IV glucose push and is advised to eat and check his sugar before exercise.']::text[]),
(357,'Easy',array['Neurology','Orthopedics & Sports Medicine']::text[],'Concussion','concussion','concussion',array['A 16-year-old rugby player is taken off the field during a match.','He collided head-to-head with another player and seemed dazed for a moment.','He did not lose consciousness, but he cannot remember the play just before the collision.','He complains of a headache, feeling dizzy, and being sensitive to light and noise.','His neurological exam is normal, and he has no repeated vomiting or worsening symptoms.','No scan is needed; he rests and returns to sport step by step once he is free of symptoms.']::text[]),
(358,'Easy',array['Otolaryngology (ENT)','Immunology']::text[],'Allergic Rhinitis (Hay Fever)','allergic-rhinitis','allergic-rhinitis',array['A 20-year-old student comes in because she has been feeling miserable for a few weeks.','She says it happens every spring and makes it hard to focus on her studies.','She had eczema as a child, and her brother has asthma.','She has a runny, blocked nose, sneezing fits, and itchy, watery eyes.','Her nasal lining is pale and swollen, and she has dark circles under her eyes.','Skin-prick testing is positive for grass pollen; she starts a steroid nasal spray and a non-sedating antihistamine.']::text[]),
(359,'Easy',array['Rheumatology & Immunology','Orthopedics & Sports Medicine']::text[],'Osteoarthritis','osteoarthritis','osteoarthritis',array['A 66-year-old woman visits her doctor about knee pain that has bothered her for several years.','The pain gets worse with walking and climbing stairs and eases with rest.','She is overweight and used to work as a cleaner, kneeling for many hours.','Her knees are stiff for about 15 minutes in the morning and creak when she moves them.','Her knees are bony and enlarged, without warmth, and X-rays show joint space narrowing, osteophytes, and subchondral sclerosis.','She starts weight loss, physiotherapy, and topical anti-inflammatories, with knee replacement as a later option.']::text[]),
(360,'Easy',array['Ophthalmology']::text[],'Dry Eye Disease','dry-eye-disease','dry-eye-disease',array['A 55-year-old woman visits the eye clinic about uncomfortable eyes.','She says her eyes feel gritty and burning, especially by the end of the day.','She works long hours on a computer in an air-conditioned office and recently went through menopause.','Her vision blurs at times but clears when she blinks.','The eyes look mildly red, and the tear film breaks up quickly on slit-lamp examination with fluorescein.','A Schirmer test shows low tear production; she starts artificial tears and screen breaks.']::text[]),
(361,'Easy',array['Obstetrics & Gynecology']::text[],'Primary Dysmenorrhea','dysmenorrhea','primary-dysmenorrhea',array['A 16-year-old girl is brought in by her mother because she misses school once a month.','She gets cramping lower tummy pain that spreads to her back and thighs.','The pain started about a year after her periods began.','It starts a few hours before her period and lasts for the first two days, with nausea and loose stools.','Her pelvic exam and ultrasound are normal.','Her pain improves with an NSAID started a day before her period, and a hormonal pill is offered if needed.']::text[]),
(362,'Easy',array['Orthopedics & Sports Medicine']::text[],'Acute Mechanical Low Back Pain','acute-mechanical-low-back-pain','acute-mechanical-low-back-pain',array['A 34-year-old warehouse worker visits his doctor about pain that started yesterday.','He felt a sudden twinge while lifting a heavy box with a twisted back.','The pain is in his lower back and gets worse when he bends, sits for long, or turns.','The muscles beside his spine are tight and tender, and moving hurts.','He has no leg weakness, numbness, bladder or bowel problems, fever, or weight loss.','No scan is needed; he is told to stay active, use simple painkillers and heat, and expect recovery within weeks.']::text[]),
(363,'Easy',array['Gastroenterology & Hepatology','Infectious Diseases']::text[],'Hepatitis A','hepatitis-a','hepatitis-a',array['A 24-year-old man visits his doctor feeling tired and sick for a week.','He has a low fever, has lost his appetite, and feels pain under his right ribs.','He came back three weeks ago from a backpacking trip where he ate street food and drank tap water.','His urine has turned dark like tea, and his stools are pale.','His eyes look yellow, and blood tests show very high ALT and AST levels.','Anti-HAV IgM is positive; he recovers with rest and fluids, and his close contacts are offered the vaccine.']::text[]),
(364,'Easy',array['Pediatrics']::text[],'Physiological Neonatal Jaundice','neonatal-jaundice-physiological','physiological-neonatal-jaundice',array['A healthy term baby girl is checked at home by a midwife on day three of life.','Her parents noticed that her skin looks more yellow today.','She is breastfeeding well, is alert, and has plenty of wet nappies.','The yellow colour started on her face on day two and has spread down to her chest.','Her bilirubin is mildly raised and is mostly unconjugated, below the treatment line on the chart.','It comes from the newborn liver''s immature handling of bilirubin, and it fades within two weeks with good feeding.']::text[]),
(365,'Easy',array['Orthopedics & Sports Medicine','Pediatrics']::text[],'Osgood-Schlatter Disease','osgood-schlatter-disease','osgood-schlatter-disease',array['A 13-year-old boy comes to the clinic with knee pain for two months.','He plays basketball almost every day and has grown a lot in the past year.','The pain is worse when he jumps, runs, kneels, or climbs stairs and eases with rest.','There is a tender, bony bump just below his kneecap on the front of the shin.','An X-ray shows a raised and slightly fragmented tibial tuberosity.','It is irritation where the patellar tendon pulls on the growth plate; he rests, ices, and stretches, and it settles after growth.']::text[]),
(366,'Easy',array['Dermatology']::text[],'Melasma','melasma','melasma',array['A 32-year-old woman visits the skin clinic about dark patches on her face.','She says they appeared slowly over the last year and get darker in summer.','She started the oral contraceptive pill shortly before the patches appeared.','There are flat, brown patches on both of her cheeks, forehead, and upper lip.','The patches are symmetrical, have irregular edges, and do not itch or scale.','She starts daily broad-spectrum sunscreen and a lightening cream with hydroquinone, and her pill is reviewed.']::text[]),
(367,'Easy',array['Gastroenterology & Hepatology','Surgery & Trauma']::text[],'Acute Diverticulitis','acute-diverticulitis','acute-diverticulitis',array['A 64-year-old woman visits the emergency department with tummy pain for two days.','The pain is constant, in her lower left abdomen, and slowly getting worse.','She eats a low-fibre diet and has had constipation for years.','She has a fever of 38.3 °C and feels sick, and her lower left abdomen is very tender.','Blood tests show a raised white cell count and C-reactive protein.','CT shows inflamed out-pouchings of the sigmoid colon with fat stranding but no abscess, and she starts antibiotics.']::text[]),
(368,'Easy',array['Hematology & Oncology','Vascular Surgery']::text[],'Deep Vein Thrombosis (DVT)','deep-vein-thrombosis','deep-vein-thrombosis',array['A 42-year-old woman visits the clinic about a painful left leg.','The pain started three days ago in her calf and feels like a cramp.','She returned last week from a 14-hour flight and takes the combined pill.','Her left calf is swollen, warm, and tender, measuring 3 cm wider than the right.','Her D-dimer is raised.','A compression ultrasound shows a clot in the popliteal vein that does not compress, and she starts a direct oral anticoagulant.']::text[]),
(369,'Medium',array['Neurology']::text[],'Multiple Sclerosis','multiple-sclerosis','multiple-sclerosis',array['A 28-year-old woman visits her doctor because her vision has been strange for a few days.','Two years ago she had tingling and numbness in her legs that went away on its own after a month.','She grew up in northern Europe and has low vitamin D.','Her right eye hurts when she moves it, colours look washed out, and the right pupil reacts weakly to a swinging light.','She also feels an electric shock down her spine when she bends her neck forward.','Brain MRI shows several periventricular white matter lesions at different ages, and her spinal fluid has oligoclonal bands.']::text[]),
(370,'Medium',array['Infectious Diseases','Neurology']::text[],'Acute Bacterial Meningitis','acute-bacterial-meningitis','bacterial-meningitis',array['A 19-year-old university student is brought to the emergency department by his roommate.','He has had a worsening headache and vomiting since last night and now seems confused.','He lives in a crowded student hall and missed some of his teenage vaccines.','He has a fever of 39.6 °C, a stiff neck, and cannot stand bright light.','Small purple spots that do not fade under a glass appear on his legs.','Spinal fluid is cloudy with many neutrophils, low glucose, and Gram-negative diplococci; IV ceftriaxone and dexamethasone are started.']::text[]),
(371,'Medium',array['Infectious Diseases','Neurology']::text[],'Viral Meningitis','viral-meningitis','viral-meningitis',array['A 24-year-old man comes to the emergency department in late summer with a bad headache.','The headache started yesterday together with a fever and muscle aches.','His young nephew had a cold and a rash last week.','His neck is stiff and light hurts his eyes, but he is fully alert and oriented.','He has no rash, no seizures, and no focal neurological signs.','Spinal fluid is clear with raised lymphocytes, normal glucose, and a positive enterovirus PCR; he recovers with supportive care.']::text[]),
(372,'Medium',array['Cardiology']::text[],'Acute Decompensated Heart Failure','acute-decompensated-heart-failure-pulmonary-edema','congestive-heart-failure',array['A 74-year-old man is brought to the emergency department in the middle of the night, struggling to breathe.','Over the past week he needed more pillows to sleep and woke up gasping for air.','He had a heart attack two years ago and recently stopped his water tablets because they made him pass urine too often.','He is sitting upright, sweating, with pink frothy sputum and crackles in both lungs.','His neck veins are raised, his ankles are swollen, and a third heart sound is heard.','Chest X-ray shows bat-wing shadows and Kerley B lines, BNP is very high, and IV furosemide and oxygen are given.']::text[]),
(373,'Medium',array['Endocrinology','Emergency Medicine & Toxicology']::text[],'Hyperosmolar Hyperglycemic State (HHS)','hyperosmolar-hyperglycemic-state-hhs','hyperosmolar-hyperglycemic-state',array['An 80-year-old woman from a care home is brought in because she has become very drowsy over several days.','Staff say she has been very thirsty, passing lots of urine, and recently had a chest infection.','She has type 2 diabetes treated with tablets.','She is severely dehydrated, with dry lips, low blood pressure, and a fast heart rate.','Her blood glucose is 52 mmol/L (940 mg/dL) and her serum osmolality is 360 mOsm/kg.','Ketones are only slightly raised and her pH is normal; she is treated with slow IV fluids, then low-dose insulin.']::text[]),
(374,'Medium',array['Gastroenterology & Hepatology']::text[],'Irritable Bowel Syndrome (IBS)','irritable-bowel-syndrome-ibs','irritable-bowel-syndrome',array['A 29-year-old woman visits her doctor about tummy trouble that has come and gone for over a year.','She gets cramping lower abdominal pain several days a week, with bloating that is worse by the evening.','The symptoms flare when she is stressed at work.','Her bowel habits switch between loose stools and constipation, and the pain eases after she opens her bowels.','She has no weight loss, rectal bleeding, or night-time symptoms, and her blood count, CRP, and coeliac screen are normal.','Faecal calprotectin is normal; she starts a low-FODMAP diet, an antispasmodic, and soluble fibre.']::text[]),
(375,'Medium',array['Gastroenterology & Hepatology','Infectious Diseases']::text[],'Hepatitis B','hepatitis-b','hepatitis-b',array['A 30-year-old man visits his doctor feeling tired and achy for three weeks.','He has joint pain, a mild rash, and a poor appetite.','He had a tattoo done abroad two months ago and has had new sexual partners.','His eyes have become yellow and his urine is dark.','His ALT is over 1,500 U/L.','Serology shows a positive surface antigen and IgM anti-core antibody; he is monitored, and his partners are tested and vaccinated.']::text[]),
(376,'Medium',array['Nephrology & Urology','Pediatrics']::text[],'Post-Streptococcal Glomerulonephritis','acute-glomerulonephritis','post-streptococcal-glomerulonephritis',array['A 7-year-old boy is brought to the clinic because his face looks puffy in the mornings.','His mother says he has been passing less urine than usual for a few days.','He had a sore throat with fever about two weeks ago that got better on its own.','His urine is dark brown like cola, and his eyelids and ankles are swollen.','His blood pressure is high for his age, and his urine shows red cell casts and some protein.','His C3 complement level is low and his anti-streptolysin O titre is high; he improves with salt restriction and diuretics.']::text[]),
(377,'Medium',array['Orthopedics & Sports Medicine','Infectious Diseases']::text[],'Septic Arthritis','septic-arthritis','septic-arthritis',array['A 70-year-old man comes to the emergency department because his knee has become very painful over a day.','He has a fever and chills and feels generally unwell.','He has rheumatoid arthritis, takes steroids, and had a steroid injection into the same knee last week.','His right knee is hot, red, and swollen, and he refuses to bend it even slightly.','His white cell count and CRP are high.','Joint fluid is cloudy with over 80,000 white cells, mostly neutrophils, and grows Staphylococcus aureus; the joint is washed out and IV antibiotics given.']::text[]),
(378,'Medium',array['Orthopedics & Sports Medicine','Pediatrics']::text[],'Slipped Capital Femoral Epiphysis (SCFE)','slipped-capital-femoral-epiphysis','slipped-capital-femoral-epiphysis',array['A 12-year-old boy comes to the clinic with a limp that started a few weeks ago.','He complains of a dull pain in his left knee and thigh, which is worse after football.','He is obese and is going through a growth spurt.','When his left hip is bent, the thigh rolls outwards on its own, and inward rotation is limited.','His knee looks completely normal on examination.','A frog-leg hip X-ray shows the femoral head slipped backward off the neck, like ice cream sliding off a cone; he has urgent pinning surgery.']::text[]),
(379,'Medium',array['Hematology & Oncology','Surgery & Trauma']::text[],'Breast Cancer','breast-cancer','breast-cancer',array['A 52-year-old woman visits her doctor about a change she noticed in her breast while showering.','She has no pain and feels otherwise well.','Her mother had a similar problem at age 48, and she started her periods early and never had children.','There is a hard, irregular, painless lump in the upper outer part of her left breast, fixed to the tissue around it.','The skin over it is dimpled like orange peel, and there is a firm lymph node in her left armpit.','Mammogram shows a spiculated mass, and core biopsy confirms invasive ductal carcinoma that is oestrogen-receptor positive.']::text[]),
(380,'Medium',array['Pulmonology','Hematology & Oncology']::text[],'Lung Cancer','lung-cancer','lung-cancer',array['A 67-year-old man visits his doctor about a cough that has not gone away for two months.','He has lost 7 kg without trying and feels tired all the time.','He has smoked 40 cigarettes a day for 45 years and worked with asbestos in shipyards.','He has coughed up streaks of blood twice this week, and his voice has become hoarse.','His fingertips are clubbed, and a chest X-ray shows a mass near the left hilum.','CT-guided biopsy confirms squamous cell carcinoma, and staging scans are arranged.']::text[]),
(381,'Medium',array['Nephrology & Urology','Emergency Medicine & Toxicology']::text[],'Hyperkalemia','hyperkalemia','hyperkalemia',array['A 69-year-old man is brought to the emergency department because his legs feel weak and heavy.','He has felt a strange fluttering in his chest since this morning.','He has chronic kidney disease and recently started spironolactone with his ramipril.','His heart rate is slow and irregular, and his muscle strength is reduced.','His ECG shows tall, peaked T waves, flattened P waves, and widening QRS complexes.','Serum potassium is 7.2 mmol/L; he receives IV calcium gluconate, insulin with glucose, and nebulised salbutamol.']::text[]),
(382,'Medium',array['Cardiology']::text[],'Supraventricular Tachycardia (SVT)','supraventricular-tachycardia-svt','paroxysmal-supraventricular-tachycardia',array['A 26-year-old woman comes to the emergency department because her heart is racing.','It started suddenly, like a switch flipping, while she was bending to tie her shoe.','She has had shorter similar episodes before that stopped on their own, and she drinks lots of coffee.','She feels light-headed and has a pounding feeling in her neck, but her blood pressure is normal.','The ECG shows a regular narrow-complex tachycardia at 190 bpm with no visible P waves.','A modified Valsalva manoeuvre fails, but IV adenosine returns her to normal sinus rhythm at once.']::text[]),
(383,'Medium',array['Cardiology']::text[],'Takotsubo Cardiomyopathy','takotsubo-cardiomyopathy','takotsubo-cardiomyopathy',array['A 68-year-old woman is brought to the emergency department with crushing chest pain and shortness of breath.','The pain began during her husband''s funeral earlier this afternoon.','She has no known heart disease and has gone through menopause.','Her ECG shows ST elevation in the front chest leads, and her troponin is mildly raised.','Urgent coronary angiography shows no blocked arteries.','The left ventricle balloons at the apex like an octopus pot, and it recovers fully over the next few weeks.']::text[]),
(384,'Medium',array['Neurology','Surgery & Trauma']::text[],'Subdural Hematoma','subdural-hematoma','subdural-hematoma',array['An 82-year-old man is brought to the doctor by his daughter because he has become more confused over three weeks.','He has been sleepy, forgetful, and complaining of headaches.','He drinks heavily, takes warfarin, and fell and hit his head about a month ago.','His confusion seems to come and go from day to day.','He has mild weakness of his left arm and leg.','CT of the head shows a crescent-shaped collection over the right side of the brain that crosses suture lines; it is drained through burr holes.']::text[]),
(385,'Medium',array['Vascular Surgery','Emergency Medicine & Toxicology']::text[],'Abdominal Aortic Aneurysm (AAA)','abdominal-aortic-aneurysm','abdominal-aortic-aneurysm',array['A 71-year-old man collapses at home and is brought to the emergency department.','Before collapsing, he complained of sudden severe pain in his tummy and back.','He is a heavy smoker with high blood pressure, and his brother died suddenly in his sixties.','He is pale and sweaty, with a heart rate of 130 bpm and blood pressure of 80/50 mmHg.','A pulsating, expanding mass is felt above his belly button.','Bedside ultrasound shows a 7 cm infrarenal aortic dilation with blood around it, and he is rushed to theatre for repair.']::text[]),
(386,'Medium',array['Gastroenterology & Hepatology','Surgery & Trauma']::text[],'Acute Cholangitis','acute-cholangitis','acute-cholangitis',array['A 70-year-old woman is brought to the emergency department with fever and shaking chills.','She has had pain under her right ribs since yesterday.','She has known gallstones and is waiting for gallbladder surgery.','Her skin and eyes have turned yellow, and she is becoming confused with low blood pressure.','Blood tests show high bilirubin, high alkaline phosphatase, and a raised white cell count.','Ultrasound shows a dilated common bile duct with a stone; she receives IV antibiotics and urgent ERCP drainage.']::text[]),
(387,'Medium',array['Obstetrics & Gynecology','Surgery & Trauma']::text[],'Ovarian Torsion','ovarian-torsion','ovarian-torsion',array['A 24-year-old woman is brought to the emergency department with sudden severe lower abdominal pain.','The pain started while she was dancing and is now on the right side, with repeated vomiting.','She was told last year that she has a cyst on one of her ovaries.','She has no fever, and her pregnancy test is negative.','There is a tender mass on the right side during pelvic examination.','Ultrasound shows an enlarged right ovary with a twisted pedicle (whirlpool sign) and poor blood flow, and she has emergency laparoscopic detorsion.']::text[]),
(388,'Hard',array['Endocrinology','Emergency Medicine & Toxicology']::text[],'Adrenal Crisis','adrenal-crisis','adrenal-crisis',array['A 45-year-old man is brought to the emergency department with severe vomiting and abdominal pain.','He has had diarrhoea and fever for two days and now feels faint when he stands.','He has taken prednisolone for years for asthma but ran out of tablets a week ago.','His blood pressure is 70/40 mmHg and does not improve after two litres of IV fluid.','His sodium is low, potassium is high, and glucose is low.','A random cortisol is very low; he improves quickly after IV hydrocortisone 100 mg and more fluids.']::text[]),
(389,'Hard',array['Gastroenterology & Hepatology','Hematology & Oncology']::text[],'Hepatocellular Carcinoma','hepatocellular-carcinoma','hepatocellular-carcinoma',array['A 61-year-old man visits his doctor feeling tired with a dull ache under his right ribs.','He has lost his appetite and 6 kg over three months.','He has had hepatitis B since childhood and drinks alcohol daily.','His liver is enlarged, hard, and knobbly, and a bruit can be heard over it.','His alpha-fetoprotein level is markedly raised.','Multiphase CT shows a liver mass that lights up in the arterial phase and washes out in the late phase.']::text[]),
(390,'Hard',array['Hematology & Oncology','Nephrology & Urology']::text[],'Tumor Lysis Syndrome','tumor-lysis-syndrome','tumor-lysis-syndrome',array['A 22-year-old man in the cancer ward develops nausea and muscle cramps.','His urine output has dropped sharply over the last 24 hours.','He was diagnosed with a fast-growing lymphoma and started his first chemotherapy two days ago.','He feels tingling around his mouth and has twitching in his hands, and his ECG shows peaked T waves.','His potassium, phosphate, uric acid, and creatinine are high, while his calcium is low.','He receives aggressive IV fluids and rasburicase, and dialysis is arranged for his kidney failure.']::text[]),
(391,'Hard',array['Hematology & Oncology','Pulmonology']::text[],'Superior Vena Cava Syndrome','superior-vena-cava-syndrome','superior-vena-cava-syndrome',array['A 63-year-old man visits his doctor because his shirt collars feel tight.','Over three weeks he has had a feeling of fullness in his head that is worse when he bends over or lies down.','He is a long-term heavy smoker who has recently lost weight.','His face, neck, and arms are swollen, and his face turns red and puffy when he raises his arms above his head.','Many dilated veins are visible across his upper chest wall.','CT shows a large right upper mediastinal mass compressing a large vein; biopsy shows small cell lung cancer and a stent is placed.']::text[]),
(392,'Hard',array['Dermatology','Emergency Medicine & Toxicology']::text[],'Toxic Epidermal Necrolysis (TEN)','toxic-epidermal-necrolysis','toxic-epidermal-necrolysis',array['A 40-year-old woman visits the emergency department with fever, sore eyes, and painful skin.','She had flu-like symptoms for three days before the skin pain began.','She started lamotrigine for epilepsy three weeks ago.','Painful dusky red patches spread fast over her trunk and form large, flaccid blisters, and her lips, mouth, and eyes have erosions.','Gentle sideways pressure on normal-looking skin peels off the top layer, and over 30% of her body surface is detached.','Skin biopsy shows full-thickness epidermal necrosis; the drug is stopped and she is moved to a burns unit.']::text[]),
(393,'Hard',array['Infectious Diseases','Tropical Medicine']::text[],'Typhoid Fever','typhoid-fever','typhoid-fever',array['A 26-year-old man visits his doctor with a fever that has got higher every day for a week.','He has a headache, a dull abdominal pain, and constipation.','He returned three weeks ago from visiting family in South Asia, where he drank untreated water.','His pulse is only 78 bpm despite a temperature of 39.8 °C.','There are a few faint pink spots on his abdomen, and his spleen is slightly enlarged.','Blood cultures grow Salmonella Typhi, and he starts azithromycin because of local resistance patterns.']::text[]),
(394,'Hard',array['Hematology & Oncology']::text[],'Thrombotic Thrombocytopenic Purpura (TTP)','thrombotic-thrombocytopenic-purpura','thrombotic-thrombocytopenic-purpura',array['A 35-year-old woman is brought to the emergency department because she has become confused and has a headache.','She has had easy bruising and feeling tired for a week.','She has no known illness and takes no regular medication.','She has a fever, purple spots on her legs, and slurred speech that comes and goes.','Her platelet count is 12 × 10⁹/L, her blood film shows many fragmented red cells, LDH is high, and creatinine is mildly raised.','ADAMTS13 activity is below 10%; she starts urgent plasma exchange and steroids.']::text[]),
(395,'Hard',array['Gastroenterology & Hepatology']::text[],'Primary Biliary Cholangitis (PBC)','primary-biliary-cholangitis','primary-biliary-cholangitis',array['A 50-year-old woman visits her doctor because she feels exhausted all the time.','She also has severe itching all over her body, worst at night, without any rash.','She has hypothyroidism and dry eyes and mouth.','There are yellow fatty deposits around her eyelids, and her liver is mildly enlarged.','Her alkaline phosphatase is very high, and her ALT is only slightly raised.','Anti-mitochondrial antibodies are strongly positive; she starts ursodeoxycholic acid.']::text[]),
(396,'Hard',array['Rheumatology & Immunology','Genetics']::text[],'Familial Mediterranean Fever (FMF)','familial-mediterranean-fever','familial-mediterranean-fever',array['A 14-year-old boy is brought to the clinic because of repeated attacks of fever.','Each attack lasts two to three days, then he is completely well between attacks.','His family is of Armenian origin, and a cousin has a similar problem.','During attacks he has severe abdominal pain that once led to surgery, which found a normal appendix.','Some attacks bring chest pain on breathing or a red, swollen ankle, and CRP is very high during them.','Genetic testing shows MEFV mutations; daily colchicine stops the attacks and protects against amyloidosis.']::text[]),
(397,'Hard',array['Hematology & Oncology']::text[],'Acute Myeloid Leukemia (AML)','acute-myeloid-leukemia','acute-myeloid-leukemia',array['A 65-year-old man visits his doctor because he has felt very tired for a month.','He has had two chest infections and bleeding gums when he brushes his teeth.','He was treated with chemotherapy for lymphoma ten years ago.','He is pale, with small red dots on his legs, and his gums are swollen.','His blood count shows anaemia, low platelets, and a high white count with many immature blast cells.','The blasts contain needle-shaped Auer rods and are myeloperoxidase positive, with over 20% blasts in the bone marrow.']::text[]),
(398,'Hard',array['Neurology','Orthopedics & Sports Medicine']::text[],'Cauda Equina Syndrome','cauda-equina-syndrome','cauda-equina-syndrome',array['A 42-year-old man comes to the emergency department with severe low back pain.','He has had back pain for weeks, but today pain shoots down both legs.','He works as a removal man and lifts heavy furniture every day.','He has numbness around his anus, genitals, and inner thighs, like sitting on a saddle.','He has not passed urine for 12 hours, and a bladder scan shows 900 mL retained; anal tone is reduced.','Urgent MRI shows a large central L4-L5 disc prolapse compressing the nerve roots, and he has emergency decompression.']::text[]),
(399,'Hard',array['Neurology','Hematology & Oncology']::text[],'Cerebral Venous Sinus Thrombosis (CVST)','cerebral-venous-sinus-thrombosis','cerebral-venous-sinus-thrombosis',array['A 29-year-old woman comes to the emergency department with a headache that has worsened over five days.','The headache is worse when lying down and in the morning, and she has vomited twice.','She is two weeks after childbirth, and she was dehydrated from feeding difficulties.','She had a seizure this morning, and her vision is blurred.','Fundoscopy shows swollen optic discs, and CT shows a small bleed in the brain that does not match an arterial territory.','MR venography shows a clot in the superior sagittal sinus; she starts anticoagulation even with the small bleed.']::text[]),
(400,'Hard',array['Hematology & Oncology','Emergency Medicine & Toxicology']::text[],'Disseminated Intravascular Coagulation (DIC)','disseminated-intravascular-coagulation','disseminated-intravascular-coagulation',array['A 58-year-old man in intensive care starts to bleed from his drip sites.','He was admitted two days ago with severe sepsis from a perforated bowel.','He has no history of bleeding problems and takes no anticoagulants.','There is oozing from his catheter and gums, and his fingers and toes have turned blue and cold.','His platelets have dropped quickly, his PT and APTT are long, and his fibrinogen is low.','His D-dimer is very high and his blood film shows schistocytes; he is treated for sepsis with platelets, plasma, and cryoprecipitate.']::text[]),
(401,'Hard',array['Gastroenterology & Hepatology','Hematology & Oncology']::text[],'Pancreatic Cancer','pancreatic-cancer','pancreatic-adenocarcinoma',array['A 69-year-old man visits his doctor because he has lost 9 kg over two months.','He has a dull pain in his upper abdomen that spreads to his back and is better when he leans forward.','He smokes and was recently diagnosed with new diabetes.','His skin and eyes are yellow without pain, he itches, his urine is dark, and his stools are pale and greasy.','A smooth, non-tender gallbladder can be felt below the right ribs.','CA 19-9 is high, and CT shows a mass in the head of the pancreas with a dilated bile duct and pancreatic duct.']::text[]),
(402,'Hard',array['Orthopedics & Sports Medicine','Infectious Diseases']::text[],'Osteomyelitis','osteomyelitis','osteomyelitis',array['A 62-year-old man visits his doctor about a sore on his foot that has not healed for two months.','It recently began to smell and drain fluid.','He has long-standing type 2 diabetes with poor sugar control and numb feet.','There is a deep ulcer under his big toe joint, and a sterile metal probe touches bone at the base.','His ESR and CRP are very high, and plain X-rays show bone destruction with periosteal reaction.','MRI shows marrow oedema, bone biopsy grows Staphylococcus aureus, and he begins six weeks of antibiotics.']::text[]),
(403,'Hard',array['Pulmonology']::text[],'Bronchiectasis','bronchiectasis','bronchiectasis',array['A 48-year-old woman visits her doctor about a cough she has had for years.','Every day she coughs up large amounts of thick, smelly, yellow-green mucus, especially in the morning.','She had a severe case of whooping cough and pneumonia as a child.','She has had many chest infections a year and has coughed up blood a few times.','Coarse crackles are heard at both lung bases, and her fingertips are clubbed.','High-resolution CT shows widened airways bigger than the arteries next to them (signet ring sign); she starts airway clearance physiotherapy.']::text[]),
(404,'Hard',array['Gastroenterology & Hepatology']::text[],'Achalasia','achalasia','achalasia',array['A 38-year-old woman visits her doctor about trouble swallowing that has slowly worsened over a year.','She finds it equally hard to swallow solids and liquids.','She has lost weight and was treated for reflux, which did not help.','She brings up undigested food hours after eating, especially when lying down at night, and coughs at night.','Barium swallow shows a widened oesophagus that narrows smoothly at the bottom like a bird''s beak.','Manometry shows no peristalsis and a lower oesophageal sphincter that does not relax; she has a Heller myotomy.']::text[]),
(405,'Hard',array['Neurology','Psychiatry']::text[],'Anti-NMDA Receptor Encephalitis','anti-nmda-receptor-encephalitis','anti-nmda-receptor-encephalitis',array['A 24-year-old woman is brought to the psychiatric emergency service because her behaviour has changed dramatically.','Over two weeks she became anxious, paranoid, and started hearing voices, after a flu-like illness.','She has no history of mental illness or drug use.','She develops odd repetitive mouth and face movements, seizures, and swings in her blood pressure and heart rate.','Her spinal fluid shows raised lymphocytes, and her EEG shows a pattern called extreme delta brush.','Antibodies against NMDA receptors are found in her CSF, and pelvic MRI shows an ovarian teratoma that is removed.']::text[]),
(406,'Hard',array['Rheumatology & Immunology','Hematology & Oncology']::text[],'Antiphospholipid Syndrome','antiphospholipid-syndrome','antiphospholipid-syndrome',array['A 32-year-old woman is referred to the clinic after losing a third pregnancy.','All three losses happened after 10 weeks of pregnancy.','She had a clot in her leg two years ago, and she has lupus.','She has a lace-like purple pattern on the skin of her legs.','Her APTT is long and does not correct when mixed with normal plasma, yet she has had clots, not bleeding.','Lupus anticoagulant and anti-cardiolipin antibodies are positive on two tests 12 weeks apart; she starts warfarin.']::text[]),
(407,'Hard',array['Hematology & Oncology']::text[],'Aplastic Anemia','aplastic-anemia','aplastic-anemia',array['A 19-year-old man visits his doctor feeling tired and breathless for a month.','He has had bleeding gums, nosebleeds, and a chest infection that would not go away.','He had a bout of hepatitis without a clear cause three months ago.','He is pale with bruises and tiny red spots, but his liver, spleen, and lymph nodes are not enlarged.','His blood count shows low red cells, white cells, and platelets, with a low reticulocyte count and no abnormal cells.','Bone marrow biopsy shows an almost empty marrow replaced by fat; he is referred for stem cell transplant.']::text[]),
(408,'Hard',array['Immunology','Genetics']::text[],'Hereditary Angioedema','hereditary-angioedema','hereditary-angioedema',array['A 21-year-old man comes to the emergency department because his face and lips are swollen.','He has had attacks of swelling since his teens, often after dental work or minor injury.','His father and aunt have similar swelling episodes.','There is no itching or hives, and antihistamines and adrenaline have never helped.','Some attacks cause severe abdominal pain from swelling of the bowel wall, and his voice is becoming hoarse today.','His C4 is low and C1 esterase inhibitor level and function are low; he receives C1 inhibitor concentrate.']::text[]),
(409,'Hard',array['Neurology','Genetics']::text[],'Myotonic Dystrophy','myotonic-dystrophy','myotonic-dystrophy-type-1',array['A 35-year-old man visits his doctor about weakness in his hands.','He has trouble letting go of objects after gripping them, such as door handles.','His mother has cataracts and needed a pacemaker in her forties.','He has frontal baldness, a long thin face with drooping eyelids, and wasted jaw and neck muscles.','After he squeezes a fist he cannot quickly open it, and tapping his thumb muscle causes a slow contraction.','Genetic testing shows an expanded CTG repeat in the DMPK gene, and he is screened for heart rhythm problems.']::text[]),
(410,'Hard',array['Rheumatology & Immunology']::text[],'Sjogren Syndrome','sjogren-syndrome','sjogren-syndrome',array['A 48-year-old woman visits her doctor feeling tired with joint aches.','She needs to sip water to swallow dry food, and her teeth have developed many cavities.','Her sister has rheumatoid arthritis.','Her eyes feel gritty, like there is sand in them, and both parotid glands are swollen.','A Schirmer test shows less than 5 mm of tears in five minutes.','Anti-Ro (SSA) and anti-La (SSB) antibodies are positive, and lip biopsy shows lymphocyte clusters in the salivary glands.']::text[]),
(411,'Hard',array['Nephrology & Urology','Vascular Surgery']::text[],'Renal Artery Stenosis','renal-artery-stenosis','renal-artery-stenosis',array['A 68-year-old man is referred because his blood pressure stays high despite three medicines.','He has had sudden episodes of breathlessness from fluid on the lungs, with normal heart pumping.','He smokes and has coronary and leg artery disease.','A whooshing bruit can be heard over his upper abdomen.','His creatinine rose by 40% two weeks after he started ramipril, and his potassium is low with high renin.','CT angiography shows a severe narrowing at the origin of the left renal artery, and the right kidney is small.']::text[]),
(412,'Hard',array['Hematology & Oncology','Genetics']::text[],'Hemophilia A','hemophilia-a','hemophilia-a',array['A 2-year-old boy is brought to the clinic because his knee is swollen and he refuses to walk.','He has bruised easily since he started crawling and bled for a long time after a tongue cut.','His mother''s brother had bleeding problems and joint damage.','His right knee is warm, swollen, and tense, with no history of a major injury.','His platelet count and PT are normal, but his APTT is long and corrects when mixed with normal plasma.','Factor VIII activity is 1% of normal; he starts regular factor VIII replacement.']::text[]),
(413,'Hard',array['Hematology & Oncology','Pediatrics']::text[],'Acute Lymphoblastic Leukemia (ALL)','acute-lymphoblastic-leukemia','acute-lymphoblastic-leukemia',array['A 4-year-old boy is brought to the clinic because he has been tired and pale for three weeks.','He has had a fever on and off and complains that his legs hurt, and he does not want to walk.','He has Down syndrome.','He has bruises and tiny red spots on his skin, swollen lymph nodes, and an enlarged liver and spleen.','His blood count shows anaemia, low platelets, and many blasts on the film.','Bone marrow shows over 25% lymphoblasts that are TdT positive and CD10 positive, and he starts chemotherapy.']::text[]),
(414,'Hard',array['Pediatrics','Surgery & Trauma']::text[],'Hirschsprung Disease','hirschsprung-disease','hirschsprung-disease',array['A 3-day-old baby boy is checked because his tummy is getting bigger.','He is vomiting green fluid and feeding poorly.','He did not pass his first stool (meconium) in the first 48 hours of life.','His abdomen is swollen and tight, and a rectal exam is followed by an explosive gush of stool and gas.','Contrast enema shows a narrow rectum with a widened colon above it.','Rectal suction biopsy shows no ganglion cells in the bowel wall, and he has a pull-through operation.']::text[]),
(415,'Hard',array['Pediatrics','Pulmonology']::text[],'Neonatal Respiratory Distress Syndrome','neonatal-respiratory-distress-syndrome','neonatal-respiratory-distress-syndrome',array['A baby boy is born by emergency caesarean section and soon starts struggling to breathe.','His breathing gets worse over the first few hours of life.','He was born at 29 weeks, and his mother has diabetes and did not get steroid injections before delivery.','He grunts, his nostrils flare, and the skin between his ribs pulls in with each breath, with a blue tinge.','His chest X-ray shows a fine ground-glass pattern in both lungs with air bronchograms and low lung volumes.','It is caused by a lack of surfactant; he receives CPAP and surfactant through a tube into his lungs.']::text[]),
(416,'Hard',array['Rheumatology & Immunology','Dermatology']::text[],'Dermatomyositis','dermatomyositis','dermatomyositis',array['A 52-year-old woman visits her doctor because combing her hair and climbing stairs have become hard.','The weakness has slowly worsened over two months, and her muscles ache.','She has also lost weight without trying.','There is a purple-red rash on her upper eyelids with swelling, and a red rash on her upper chest and back.','Raised scaly red bumps cover the knuckles of her hands, and her creatine kinase is very high.','Anti-Mi-2 antibodies are positive and muscle biopsy shows inflammation around fascicles; she is screened for an ovarian cancer.']::text[]),
(417,'Hard',array['Pediatrics','Rheumatology & Immunology']::text[],'IgA Vasculitis (Henoch-Schönlein Purpura)','iga-vasculitis-henoch-schonlein-purpura','iga-vasculitis',array['A 6-year-old boy is brought to the clinic with tummy pain and a rash.','He had a cold with a sore throat two weeks ago.','His ankles and knees are swollen and painful, and he limps.','Raised purple spots that can be felt are spread over his buttocks and the backs of his legs, while his platelet count is normal.','His urine dipstick shows blood and a little protein.','Skin biopsy shows IgA deposits in small vessel walls; he is managed with rest and pain relief, and his urine is followed up.']::text[]),
(418,'Hard',array['Rheumatology & Immunology']::text[],'Psoriatic Arthritis','psoriatic-arthritis','psoriatic-arthritis',array['A 41-year-old man visits his doctor about painful joints in his hands for six months.','His joints are stiff in the morning for about an hour.','He has had red scaly patches on his elbows and scalp for ten years.','One of his fingers is swollen like a sausage, and the joints closest to his fingertips are tender.','His nails have small pits and are lifting from the nail bed, and his heel hurts where the Achilles tendon attaches.','Rheumatoid factor is negative, and hand X-rays show a pencil-in-cup deformity; he starts methotrexate.']::text[]),
(419,'Hard',array['Nephrology & Urology','Infectious Diseases']::text[],'Acute Bacterial Prostatitis','acute-bacterial-prostatitis','acute-bacterial-prostatitis',array['A 55-year-old man comes to the emergency department with fever and shaking chills.','He has burning when passing urine and needs to go often and urgently.','He had a prostate biopsy one week ago.','He has pain between his scrotum and anus and finds it hard to start his stream.','A gentle rectal exam shows a very tender, hot, swollen, boggy gland.','Urine culture grows E. coli, and he starts IV antibiotics followed by a long oral course of a quinolone.']::text[]),
(420,'Hard',array['Vascular Surgery','Emergency Medicine & Toxicology']::text[],'Acute Limb Ischemia','acute-limb-ischemia','acute-limb-ischemia',array['A 72-year-old woman comes to the emergency department with sudden pain in her right leg that started two hours ago.','The pain is severe and does not ease with rest.','She has atrial fibrillation but stopped her blood thinner because of a nosebleed.','Her right leg is pale and cold from mid-thigh down, with tingling in her foot.','No pulses can be felt below the right groin, and she can barely move her toes.','CT angiography shows a sudden cut-off of the common femoral artery from an embolus; she has urgent embolectomy.']::text[]),
(421,'Hard',array['Infectious Diseases','Gastroenterology & Hepatology']::text[],'Clostridioides difficile Colitis','clostridioides-difficile-colitis','clostridioides-difficile-infection',array['A 76-year-old woman in hospital develops frequent watery diarrhoea.','She has more than six bowel movements a day with crampy lower abdominal pain.','She was given clindamycin a week ago for a skin infection and takes a proton pump inhibitor.','She has a fever and a very high white cell count of 22 × 10⁹/L.','Her stool smells unusual, and there is no blood in it.','Stool testing finds toxin from a spore-forming bacterium, and she starts oral vancomycin with strict hand-washing.']::text[]),
(422,'Hard',array['Gastroenterology & Hepatology','Emergency Medicine & Toxicology']::text[],'Esophageal Variceal Bleeding','esophageal-variceal-bleeding','esophageal-varices',array['A 54-year-old man is brought to the emergency department after vomiting a large amount of blood.','He feels dizzy and faint and has passed black, sticky stools.','He has drunk heavily for 25 years.','He has spider veins on his chest, red palms, a swollen tummy with fluid, and an enlarged spleen.','His platelets are low, his INR is high, and his blood pressure is 85/50 mmHg.','He receives terlipressin and antibiotics, and endoscopy shows bleeding dilated veins in the lower oesophagus that are banded.']::text[]),
(423,'Hard',array['Cardiology']::text[],'Wolff-Parkinson-White Syndrome','wolff-parkinson-white-syndrome','wolff-parkinson-white-syndrome',array['A 22-year-old man comes to the clinic because of episodes of a racing heart since his teens.','The episodes start and stop suddenly and sometimes make him feel faint.','He plays competitive football and has no other illnesses.','Between episodes his ECG shows a short PR interval.','There is also a slurred upstroke at the start of the QRS complex, making it slightly wide.','An electrophysiology study finds an extra pathway between the atria and ventricles, and it is removed by catheter ablation.']::text[]),
(424,'Hard',array['Infectious Diseases','Otolaryngology (ENT)']::text[],'Lemierre Syndrome','lemierre-syndrome','lemierre-syndrome',array['A 19-year-old student is admitted with high fever and rigors.','Ten days ago he had a bad sore throat that seemed to get better.','He is otherwise fit and well, with no medical history.','He has a painful, swollen area along the side of his neck below the jaw angle.','He becomes short of breath, and chest CT shows several small cavitating nodules in both lungs.','Neck ultrasound shows a clot in the internal jugular vein, and blood cultures grow Fusobacterium necrophorum.']::text[]),
(425,'Hard',array['Otolaryngology (ENT)']::text[],'Sudden Sensorineural Hearing Loss','sudden-sensorineural-hearing-loss','sudden-sensorineural-hearing-loss',array['A 46-year-old man comes to the ENT clinic because something is wrong with his left ear.','He woke up yesterday with his left ear feeling blocked.','He had a mild cold a week ago and is otherwise healthy.','He has a ringing noise in that ear and felt briefly dizzy, and his ear canal and eardrum look normal.','A tuning fork placed on his forehead sounds louder in the right ear.','An audiogram shows a drop of over 30 dB across three frequencies in the left ear, and he starts high-dose steroids straight away.']::text[]),
(426,'Hard',array['Infectious Diseases','Pediatrics']::text[],'Parvovirus B19 Infection (Fifth Disease)','parvovirus-b19-infection','erythema-infectiosum',array['A 7-year-old girl is brought to the clinic with a rash after a mild cold last week.','She had a low fever and a runny nose, which have now gone away.','Her younger brother has hereditary spherocytosis.','Both of her cheeks are bright red, as if she had been slapped, with a pale area around her mouth.','A lacy, net-like rash then appears on her arms and legs and gets brighter after a warm bath.','Her brother later becomes very pale with a low reticulocyte count, showing the virus attacks red cell precursors.']::text[]),
(427,'Hard',array['Infectious Diseases','Pulmonology']::text[],'Pneumocystis Pneumonia (PCP)','pneumocystis-pneumonia-pcp','pneumocystis-pneumonia',array['A 36-year-old man visits his doctor feeling breathless for three weeks.','He has a dry cough, low fever, and has lost weight.','He has never been tested for HIV and has had oral thrush recently.','His oxygen level drops sharply when he walks, but his lungs sound almost normal.','Chest X-ray shows fine, wispy shadows in both lungs spreading from the hila, and his LDH is high.','His CD4 count is 80 cells/µL, and silver stain of sputum shows fungal cysts; he starts high-dose co-trimoxazole and steroids.']::text[]),
(428,'Hard',array['Infectious Diseases','Pediatrics']::text[],'Cat-Scratch Disease','cat-scratch-disease','cat-scratch-disease',array['A 10-year-old boy is brought to the clinic with a lump in his armpit.','He has had a low fever and has felt tired for a week.','His family adopted a new kitten a month ago.','There is a small, crusted red bump on the back of his right hand.','A single tender, swollen lymph node is found in his right armpit.','Serology for Bartonella henselae is positive, and the swelling slowly resolves over a few months with azithromycin.']::text[]),
(429,'Hard',array['Infectious Diseases','Orthopedics & Sports Medicine']::text[],'Pott Disease (Spinal Tuberculosis)','pott-disease-spinal-tuberculosis','pott-disease',array['A 35-year-old man visits his doctor with back pain that has slowly worsened for four months.','He has night sweats, low fevers in the evening, and has lost weight.','He moved from a country where tuberculosis is common and lived in a crowded hostel.','There is a sharp angled bump in his mid back, and he has weakness and stiffness in his legs.','MRI shows destruction of two thoracic vertebrae and the disc between them, with an abscess beside the spine.','Biopsy shows caseating granulomas and acid-fast bacilli; he starts a long course of anti-tuberculosis treatment.']::text[]),
(430,'Hard',array['Neurology','Ophthalmology']::text[],'Horner Syndrome','horner-syndrome','horner-syndrome',array['A 58-year-old man is told by his wife that one of his eyes looks different.','He has no change in vision and no eye pain.','He has smoked heavily for 40 years and has had a dull ache in his right shoulder and arm.','His right upper eyelid droops slightly, and his right pupil is smaller, most noticeably in dim light.','The right side of his forehead does not sweat.','Apraclonidine drops make the small pupil dilate, and chest CT shows a tumour at the top of the right lung.']::text[]),
(431,'Hard',array['Rheumatology & Immunology','Vascular Surgery']::text[],'Raynaud Phenomenon','raynaud-phenomenon','raynaud-phenomenon',array['A 24-year-old woman visits her doctor about her fingers during winter.','She notices the problem when she reaches into the freezer or feels stressed.','She smokes and her mother had a similar problem.','Her fingers first turn white, then blue, and then bright red as they warm up again, with throbbing and tingling.','Between attacks her hands look normal, with no ulcers, and nailfold capillaries are normal.','Her ANA is negative, so it is the primary form; she is advised to keep warm and stop smoking, with nifedipine if needed.']::text[]),
(432,'Hard',array['Psychiatry','Emergency Medicine & Toxicology']::text[],'Lithium Toxicity','lithium-toxicity','lithium-toxicity',array['A 52-year-old woman is brought to the emergency department because she has been unsteady and confused for two days.','She has had diarrhoea and vomiting and is not drinking much.','She has bipolar disorder and her GP recently started her on a water tablet and ibuprofen for knee pain.','She has a coarse tremor of her hands, slurred speech, and an unsteady walk.','Her reflexes are brisk, with muscle twitching, and her creatinine has doubled.','Her serum level of a mood stabiliser is 3.1 mmol/L, and she is started on IV fluids and haemodialysis.']::text[]),
(433,'Hard',array['Psychiatry']::text[],'Bulimia Nervosa','bulimia-nervosa','bulimia-nervosa',array['A 19-year-old university student visits her doctor about tiredness and swollen cheeks.','She says she is very worried about her weight and shape and checks the mirror many times a day.','Her weight is in the normal range, and she is a keen athlete.','In secret, she eats very large amounts of food in a short time, feeling out of control, at least twice a week.','She has calluses on the backs of her knuckles, eroded enamel on the inner surfaces of her teeth, and enlarged parotid glands.','Her potassium is low with a metabolic alkalosis from repeated vomiting; she starts cognitive behavioural therapy.']::text[]),
(434,'Hard',array['Obstetrics & Gynecology']::text[],'HELLP Syndrome','hellp-syndrome','hellp-syndrome',array['A 32-year-old woman at 34 weeks of pregnancy comes to the maternity unit feeling generally unwell.','She has nausea and pain under her right ribs and in the upper middle abdomen.','This is her first pregnancy, and her blood pressure was high at her last two check-ups.','Her blood pressure is 162/104 mmHg, and her urine shows protein.','Her platelets are 70 × 10⁹/L, her liver enzymes are high, and her LDH is raised with fragmented red cells on the film.','She receives magnesium sulfate and blood pressure treatment, and the baby is delivered urgently.']::text[]),
(435,'Hard',array['Obstetrics & Gynecology']::text[],'Placenta Previa','placenta-previa','placenta-previa',array['A 34-year-old woman at 32 weeks of pregnancy comes to the maternity unit because of bleeding.','The bleeding started suddenly while she was resting and is bright red.','She has had two caesarean sections in the past and smokes.','She has no abdominal pain or contractions, and her uterus is soft and not tender.','The baby is lying across the womb, and the heart rate on the monitor is normal.','Ultrasound through the vagina, not a finger exam, shows the placenta covering the cervix, and she is admitted for monitoring.']::text[]),
(436,'Hard',array['Ophthalmology','Neurology']::text[],'Optic Neuritis','optic-neuritis','optic-neuritis',array['A 30-year-old woman visits the eye clinic because her left eye has become blurry over three days.','She has pain around the eye that is worse when she moves her eye.','She has no history of eye problems and is otherwise healthy.','Colours look washed out to her, especially red, and the left pupil dilates when a light swings to it from the right eye.','Her optic disc looks normal on fundoscopy, and her visual field shows a central blind spot.','MRI shows enhancement of the left optic nerve; she is offered IV methylprednisolone, and her brain MRI is checked for MS.']::text[]),
(437,'Hard',array['Ophthalmology']::text[],'Central Retinal Vein Occlusion (CRVO)','central-retinal-vein-occlusion','central-retinal-vein-occlusion',array['A 68-year-old man visits the eye clinic because the vision in his right eye has become blurry.','He noticed the blur when he woke up yesterday, and it is not painful.','He has high blood pressure, diabetes, and glaucoma.','His right eye vision is reduced to counting fingers, and there is a weak pupil reaction.','Fundoscopy shows a swollen optic disc, widened twisted veins, and bleeding spread across all four quadrants.','It looks like a ''blood and thunder'' fundus; his blood pressure is controlled, and he starts anti-VEGF injections for macular oedema.']::text[]),
(438,'Hard',array['Ophthalmology','Infectious Diseases']::text[],'Orbital Cellulitis','orbital-cellulitis','orbital-cellulitis',array['A 9-year-old boy is brought to the emergency department with a swollen, painful left eye.','He has had a fever and a blocked nose for a week.','He has had several episodes of sinusitis in the past.','His eyelids are red and swollen shut, and his eye bulges forward.','Moving his eye is painful and limited, and he sees double.','CT shows ethmoid sinusitis with infection behind the orbital septum, and he starts IV antibiotics with ENT review.']::text[]),
(439,'Extreme',array['Genetics','Neurology']::text[],'Batten Disease (Neuronal Ceroid Lipofuscinosis)','batten-disease','batten-disease',array['A 6-year-old boy is brought to the eye clinic because his teachers noticed he struggles to see the board.','Over the next two years his school performance drops and he becomes forgetful.','His parents are first cousins.','His vision fails quickly, and fundoscopy shows a bull''s-eye pattern in the macula.','He later develops seizures, behaviour changes, and stiff, slow movements.','Blood film shows vacuolated lymphocytes, and genetic testing confirms a CLN3 mutation causing lipopigment storage in neurons.']::text[]),
(440,'Extreme',array['Pediatrics','Genetics']::text[],'Pierre Robin Sequence','pierre-robin-sequence','pierre-robin-sequence',array['A newborn girl struggles to breathe and feed in the first hours of life.','Her breathing is noisy and gets much worse when she lies on her back.','Pregnancy scans showed reduced amniotic fluid movements and a small chin.','She has a very small lower jaw, and her tongue falls backward into her throat.','A U-shaped gap is seen in the roof of her mouth.','Placing her on her front and using a nasopharyngeal airway helps; the small jaw caused the tongue drop and the palate gap.']::text[]),
(441,'Extreme',array['Genetics','Hematology & Oncology']::text[],'Von Hippel-Lindau Syndrome','von-hippel-lindau-syndrome','von-hippel-lindau-disease',array['A 28-year-old man visits his doctor with morning headaches and an unsteady walk.','He has had episodes of a pounding heart, sweating, and very high blood pressure.','His father died of kidney cancer at 40.','Fundoscopy shows a red, round vascular growth on the retina with a large feeding vessel.','MRI shows a cystic tumour with an enhancing nodule in the cerebellum, and CT shows multiple kidney cysts and a solid kidney mass.','Urine metanephrines are high, and genetic testing shows a mutation in a tumour suppressor gene on chromosome 3p.']::text[]),
(442,'Extreme',array['Genetics','Metabolism','Dermatology']::text[],'Hereditary Coproporphyria','hereditary-coproporphyria','hereditary-coproporphyria',array['A 30-year-old woman is admitted with severe abdominal pain and vomiting.','Her belly is soft, and scans and blood tests for usual causes are normal.','The attack began after she started a new anticonvulsant and went on a strict diet.','She has a fast heart, high blood pressure, low sodium, and weakness in her arms; her urine darkens on standing.','She also has fragile skin with blisters on the backs of her hands after sun exposure.','Urine porphobilinogen is high, and faecal coproporphyrin III is very raised; genetic testing shows a CPOX mutation.']::text[]),
(443,'Extreme',array['Genetics','Metabolism','Pediatrics']::text[],'Sanfilippo Syndrome (MPS III)','sanfilippo-syndrome-mps-iii','sanfilippo-syndrome',array['A 4-year-old boy is brought to the clinic because his speech has stopped improving.','He is extremely hyperactive, sleeps very little, and has aggressive outbursts.','He had frequent ear infections and diarrhoea as a toddler.','He has slightly coarse facial features, thick eyebrows, and coarse hair, but his height is normal.','Over the next two years he loses words he could say before.','Urine shows excess heparan sulfate only, and enzyme testing confirms a deficiency in heparan sulfate breakdown.']::text[]),
(444,'Extreme',array['Genetics','Neurology']::text[],'CARASIL','carasil','carasil',array['A 30-year-old man is brought to the clinic by his wife because he has become forgetful and irritable.','He had several episodes of severe low back pain in his twenties.','His parents are cousins, and he started going bald at 18.','He has a gait problem with stiff legs and brisk reflexes.','Brain MRI shows widespread white matter changes and small old strokes in deep brain areas, without high blood pressure.','Genetic testing finds recessive mutations in HTRA1.']::text[]),
(445,'Extreme',array['Neurology','Genetics']::text[],'Gerstmann-Sträussler-Scheinker Syndrome','gerstmann-straussler-scheinker-syndrome','gerstmann-straussler-scheinker-syndrome',array['A 45-year-old man visits a neurologist because he is clumsy and keeps losing his balance.','His symptoms have slowly worsened over two years.','His father and grandfather had a similar illness that ended in dementia in their fifties.','He has slurred speech, an unsteady wide-based walk, and jerky eye movements.','Later he develops memory loss and stiffness, while his spinal fluid tests are mostly unremarkable.','Genetic testing shows a P102L mutation in the PRNP gene, and brain tissue shows amyloid plaques.']::text[]),
(446,'Extreme',array['Pediatrics','Surgery & Trauma']::text[],'Esophageal Atresia with Tracheoesophageal Fistula','esophageal-atresia-with-tracheoesophageal-fistula','esophageal-atresia-with-tracheoesophageal-fistula',array['A newborn baby boy has a lot of frothy saliva bubbling from his mouth soon after birth.','During pregnancy his mother had too much amniotic fluid.','He also has a heart murmur and an abnormal shape of the bones of his forearm.','At his first feed he coughs, chokes, and turns blue.','A feeding tube cannot be passed into his stomach and curls back in his chest on X-ray.','The X-ray shows gas in his stomach and bowel, proving an abnormal connection from the airway; he has surgical repair.']::text[]),
(447,'Extreme',array['Genetics','Dermatology','Pulmonology']::text[],'Birt-Hogg-Dubé Syndrome','birt-hogg-dube-syndrome','birt-hogg-dube-syndrome',array['A 35-year-old man comes to the emergency department with sudden chest pain and breathlessness.','He has had a collapsed lung once before on the other side.','His mother had a kidney tumour removed at 50.','He has many small, smooth, skin-coloured bumps on his face, neck, and upper chest.','Chest CT shows multiple thin-walled cysts in the lower parts of both lungs.','Skin biopsy shows fibrofolliculomas, and genetic testing shows a mutation in the FLCN gene.']::text[]),
(448,'Extreme',array['Pediatrics','Surgery & Trauma']::text[],'Congenital Diaphragmatic Hernia','congenital-diaphragmatic-hernia','congenital-diaphragmatic-hernia',array['A newborn boy has severe breathing difficulty and turns blue right after birth.','Resuscitation with a bag and mask makes his breathing worse.','A pregnancy scan had raised concerns, but his mother missed the follow-up.','His tummy looks sunken, and his heart sounds are heard on the right side of his chest.','Breath sounds are absent on the left, and bowel sounds are heard in the left chest.','Chest X-ray shows bowel loops in the left chest through a back-left defect, and he is intubated and stabilised before repair.']::text[]),
(449,'Extreme',array['Hematology & Oncology','Neurology']::text[],'POEMS Syndrome','poems-syndrome','poems-syndrome',array['A 52-year-old man visits a neurologist about tingling and weakness in his feet that has spread up his legs over a year.','He has lost weight and feels tired, with swelling of his legs.','His skin has darkened, and he has developed breasts and erectile dysfunction.','His liver and spleen are enlarged, and he has white nails and many small red skin bumps.','Nerve tests show a demyelinating neuropathy, and blood testing finds a small lambda monoclonal protein.','Skeletal X-rays show a sclerotic bone lesion, and his VEGF level is very high.']::text[]),
(450,'Extreme',array['Dermatology','Metabolism']::text[],'Porphyria Cutanea Tarda','porphyria-cutanea-tarda','porphyria-cutanea-tarda',array['A 50-year-old man visits his doctor about skin problems on his hands for several months.','His skin tears and blisters easily after minor bumps.','He drinks heavily, has hepatitis C, and has iron overload.','The backs of his hands have blisters, erosions, scars, and small white cysts.','He also has extra hair growth on his cheeks and darker skin, and his urine is reddish-brown.','Urine porphyrins glow pink-red under Wood''s lamp; he is treated with repeated blood removal and low-dose hydroxychloroquine.']::text[]),
(451,'Extreme',array['Genetics','Neurology']::text[],'MERRF Syndrome','merrf-syndrome','merrf-syndrome',array['A 16-year-old boy visits the neurology clinic because of sudden jerks of his arms.','The jerks get worse when he moves or is startled, and he has had a few seizures.','His mother has hearing loss and his uncle has weak muscles, but his father''s side is unaffected.','He has an unsteady walk, weak muscles, and short stature.','His blood lactate is raised after exercise.','Muscle biopsy shows ragged-red fibres, and genetic testing finds a mitochondrial tRNA-Lys mutation (m.8344A>G).']::text[]),
(452,'Extreme',array['Hematology & Oncology','Pediatrics']::text[],'Langerhans Cell Histiocytosis','langerhans-cell-histiocytosis','langerhans-cell-histiocytosis',array['A 3-year-old boy is brought to the clinic with a painful lump on his skull.','He has had a scaly rash on his scalp that looks like cradle cap and has not cleared with treatment.','He also drinks and urinates a lot.','His ear has been leaking fluid, and he has a bulging eye on one side.','Skull X-ray shows sharply punched-out lytic lesions without sclerotic edges.','Biopsy shows cells that are CD1a and CD207 positive with tennis-racket granules on electron microscopy.']::text[]),
(453,'Extreme',array['Pediatrics','Pulmonology']::text[],'Congenital Lobar Emphysema','congenital-lobar-emphysema','congenital-lobar-emphysema',array['A 4-week-old baby boy is brought in because his breathing has become fast and laboured.','He has trouble feeding and has not gained much weight.','He was born at term without problems.','His left upper chest is overexpanded and sounds hollow when tapped, with reduced breath sounds.','Chest X-ray shows an over-inflated left upper lobe pushing the heart and mediastinum to the right.','CT confirms a single hyperinflated lobe from weak bronchial cartilage, and he has a lobectomy.']::text[]),
(454,'Extreme',array['Genetics','Endocrinology']::text[],'Alström Syndrome','alstrom-syndrome','alstrom-syndrome',array['A 6-month-old baby is brought in because he does not like light and his eyes wobble.','As a baby he had a period of heart failure from a weak heart muscle that later improved.','His parents are first cousins.','In childhood he becomes obese and develops hearing loss in both ears.','In his teens he develops type 2 diabetes with very high insulin levels, but has normal fingers and toes and normal intelligence.','Genetic testing confirms ALMS1 mutations, and he has progressive retinal dystrophy.']::text[]),
(455,'Extreme',array['Genetics','Neurology']::text[],'Neurofibromatosis Type 2','neurofibromatosis-type-2','neurofibromatosis-type-2',array['A 24-year-old woman visits the ENT clinic because her hearing has slowly worsened in both ears.','She also has ringing in her ears and feels off-balance.','Her father went deaf in his thirties and had brain surgery.','She had a cataract removed when she was 16.','She has a few skin tumours, but very few café-au-lait spots.','MRI shows tumours on both vestibulocochlear nerves and a meningioma, and genetic testing shows a mutation on chromosome 22.']::text[]),
(456,'Extreme',array['Genetics','Hematology & Oncology']::text[],'Hereditary Hemorrhagic Telangiectasia (HHT)','hereditary-hemorrhagic-telangiectasia','hereditary-hemorrhagic-telangiectasia',array['A 40-year-old man visits his doctor because he has frequent nosebleeds.','He has had nosebleeds since childhood and has iron deficiency anaemia.','His mother and sister also have frequent nosebleeds.','He has small red spots that fade under pressure on his lips, tongue, and fingertips.','He has a brain abscess, and a bubble echocardiogram shows a shunt through the lungs.','CT shows lung arteriovenous malformations, and genetic testing shows an ENG mutation.']::text[]),
(457,'Extreme',array['Metabolism','Genetics','Neurology']::text[],'Acute Intermittent Porphyria','acute-intermittent-porphyria','acute-intermittent-porphyria',array['A 25-year-old woman comes to the emergency department with very severe abdominal pain.','Her abdomen is soft, and scans do not explain the pain.','Her symptoms started after she began a strict diet and took a sulfonamide antibiotic.','She is anxious and confused, with a fast heart rate, high blood pressure, and weakness in her arms.','Her sodium is low, her urine turns dark red-brown on standing, and her skin has no blisters.','Urine porphobilinogen is very high, and she is treated with IV haem and glucose.']::text[]),
(458,'Extreme',array['Genetics','Neurology']::text[],'CADASIL','cadasil','cadasil',array['A 38-year-old woman visits a neurologist about migraines with a long aura.','In the past year she has had two episodes of sudden weakness of one side that lasted hours.','Her mother had dementia in her fifties without high blood pressure.','She has low mood and has become slower at thinking.','Brain MRI shows white matter changes in the front of both temporal lobes and the external capsules.','Skin biopsy shows granular osmiophilic material in the walls of small vessels, and genetic testing shows a NOTCH3 mutation.']::text[]),
(459,'Extreme',array['Pulmonology','Gastroenterology & Hepatology','Genetics']::text[],'Alpha-1 Antitrypsin Deficiency','alpha-1-antitrypsin-deficiency','alpha-1-antitrypsin-deficiency',array['A 38-year-old man visits his doctor because he gets breathless climbing one flight of stairs.','He has had a cough and wheezing for a few years.','He smoked for 10 years, and his brother had liver problems as a child.','His chest is barrel-shaped, and his lungs sound quiet.','Chest CT shows emphysema mainly in the lower lobes, and his liver enzymes are mildly raised.','His serum level of a protease inhibitor is low, and his genotype is PiZZ.']::text[]),
(460,'Extreme',array['Neurology']::text[],'Baló Concentric Sclerosis','balo-concentric-sclerosis','balo-concentric-sclerosis',array['A 30-year-old woman is admitted because she developed a headache and confusion over two weeks.','She has also developed weakness of her left arm and leg.','She has no history of neurological problems and no fever.','Her symptoms worsen quickly, and she has trouble speaking.','Brain MRI shows a large lesion with alternating rings of damaged and normal-looking white matter, like an onion.','It is a rare variant of demyelinating disease, and it is treated with high-dose steroids and plasma exchange.']::text[]),
(461,'Extreme',array['Genetics','Pediatrics']::text[],'Beckwith-Wiedemann Syndrome','beckwith-wiedemann-syndrome','beckwith-wiedemann-syndrome',array['A newborn boy is noted to be large at birth, weighing 5 kg.','He has very low blood sugar in the first days of life.','He was conceived through IVF.','He has a very large tongue, creases on his earlobes, and a hernia at his belly button.','One side of his body is slightly larger than the other.','Genetic testing shows changes on chromosome 11p15, and he is screened regularly with abdominal ultrasound and alpha-fetoprotein for Wilms tumour.']::text[]),
(462,'Extreme',array['Genetics','Neurology','Pediatrics']::text[],'Alexander Disease','alexander-disease','alexander-disease',array['A 1-year-old boy is brought to the clinic because his head seems too large.','He has had a few seizures and is behind in sitting and crawling.','There is no family history of similar problems.','His head circumference is above the 98th centile, and he has stiff, spastic legs.','Brain MRI shows white matter changes mostly in the frontal lobes, with a bright rim around the ventricles.','Genetic testing finds a GFAP mutation, and brain tissue would show Rosenthal fibres.']::text[]),
(463,'Extreme',array['Vascular Surgery','Nephrology & Urology']::text[],'Fibromuscular Dysplasia','fibromuscular-dysplasia','fibromuscular-dysplasia',array['A 32-year-old woman is referred because her blood pressure is very high for her age.','She has a whooshing sound in her ears in time with her heartbeat.','She does not smoke and has normal cholesterol.','A bruit is heard over her upper abdomen and her neck.','Her renin and aldosterone are both high.','CT angiography shows a ''string of beads'' appearance in the middle of both renal arteries, and she has balloon angioplasty.']::text[]),
(464,'Extreme',array['Hematology & Oncology']::text[],'Primary Myelofibrosis','primary-myelofibrosis','primary-myelofibrosis',array['A 66-year-old man visits his doctor feeling very tired with night sweats.','He feels full quickly after eating and has a dragging feeling on his left side.','He has lost 6 kg over the last few months.','His spleen is hugely enlarged, reaching his pelvis.','His blood film shows teardrop-shaped red cells and immature white and red cells.','A bone marrow attempt gives a dry tap, biopsy shows heavy fibrosis, and testing finds a JAK2 mutation.']::text[]),
(465,'Extreme',array['Genetics','Metabolism','Pediatrics']::text[],'Farber Disease','farber-disease','farber-disease',array['A 5-month-old baby girl is brought in because her joints are swollen and painful.','She is very irritable and cries when anyone moves her limbs.','Her parents are cousins.','She has a hoarse, weak cry and difficulty swallowing.','Firm, painful lumps appear under the skin around her joints.','Enzyme testing shows a deficiency of acid ceramidase, and genetic testing finds ASAH1 mutations.']::text[]),
(466,'Extreme',array['Pediatrics','Surgery & Trauma']::text[],'Omphalocele','omphalocele','omphalocele',array['A baby is born with a bulge in the middle of his tummy.','His mother had a raised alpha-fetoprotein level during pregnancy.','He has a very large tongue, and his blood sugar is low.','Bowel and part of the liver are seen inside the bulge, coming out at the base of the umbilical cord.','The bulge is covered by a thin, see-through sac.','Cardiac echo and genetic testing are done because of linked defects, and the sac is protected before staged closure.']::text[]),
(467,'Extreme',array['Genetics','Gastroenterology & Hepatology']::text[],'Peutz-Jeghers Syndrome','peutz-jeghers-syndrome','peutz-jeghers-syndrome',array['A 14-year-old boy comes to the emergency department with severe colicky abdominal pain and vomiting.','He has had iron deficiency anaemia for a year.','His father had bowel surgery as a teenager.','He has dark brown-blue freckles on his lips, inside his mouth, and on his fingers.','Ultrasound shows a telescoped segment of small bowel.','Surgery finds hamartomatous polyps with tree-like smooth muscle branching, and genetic testing shows an STK11 mutation.']::text[]),
(468,'Extreme',array['Metabolism','Genetics','Pediatrics']::text[],'Classic Galactosemia','classic-galactosemia','classic-galactosemia',array['A 5-day-old baby girl is brought back to the hospital because she is vomiting and very sleepy.','She started breastfeeding well but now refuses feeds.','Her parents are first cousins.','She is jaundiced, her liver is large, and she has bruises on her skin.','Blood cultures grow E. coli, her urine tests positive for reducing sugars, and slit-lamp exam shows oil-drop cataracts.','Enzyme testing finds no galactose-1-phosphate uridyltransferase, and she switches to a lactose-free soy formula.']::text[]),
(469,'Extreme',array['Rheumatology & Immunology','Dermatology','Hematology & Oncology']::text[],'Schnitzler Syndrome','schnitzler-syndrome','schnitzler-syndrome',array['A 58-year-old man visits his doctor about a rash that has come and gone for two years.','He also has fevers and feels tired and achy during flare-ups.','Antihistamines have not helped his rash at all.','The rash is made of pink raised wheals that hardly itch, and he has bone pain in his thighs and shins.','His CRP is high, and blood testing shows a monoclonal IgM kappa protein.','Bone scans show increased density in the long bones, and his symptoms disappear within days of starting anakinra.']::text[]),
(470,'Extreme',array['Genetics','Metabolism','Pediatrics']::text[],'Zellweger Syndrome','zellweger-syndrome','zellweger-syndrome',array['A newborn baby is very floppy and feeds poorly.','She has seizures in her first week of life.','Her parents are cousins, and they lost an earlier baby in infancy.','She has a high forehead, a large front soft spot, and a flat face, and her liver is enlarged.','X-rays show spotty calcifications of the knee and hip cartilage, and ultrasound shows small kidney cysts.','Her very long chain fatty acids are very high, and genetic testing shows a PEX gene mutation affecting peroxisomes.']::text[]),
(471,'Extreme',array['Neurology','Pediatrics']::text[],'Infantile Spasms (West Syndrome)','infantile-epileptic-spasms-syndrome','infantile-spasms',array['A 6-month-old baby boy is brought to the clinic because he makes strange movements.','His parents first thought it was colic or startling.','He has stopped smiling and has lost interest in toys over the past few weeks.','The episodes come in clusters, often after waking: his head drops and his arms fly up and out.','His skin shows a few pale, leaf-shaped patches under a Wood''s lamp.','EEG shows a chaotic high-voltage pattern called hypsarrhythmia, and he starts vigabatrin.']::text[]),
(472,'Extreme',array['Rheumatology & Immunology','Pulmonology']::text[],'Eosinophilic Granulomatosis with Polyangiitis (EGPA)','eosinophilic-granulomatosis-with-polyangiitis-churg-strauss','eosinophilic-granulomatosis-with-polyangiitis',array['A 44-year-old woman visits her doctor about asthma that has become much worse this year.','She has had nasal polyps and sinus problems for many years.','She now has numbness in her right foot, and she cannot lift her left wrist.','She has purple spots on her legs, and chest X-ray shows patchy shadows that move between scans.','Her blood count shows eosinophils at 25% of white cells.','p-ANCA (anti-MPO) is positive, and biopsy shows vasculitis with eosinophils and granulomas.']::text[]),
(473,'Extreme',array['Genetics','Neurology','Pediatrics']::text[],'Canavan Disease','canavan-disease','canavan-disease',array['A 4-month-old baby boy is brought to the clinic because he cannot hold his head up.','He was born healthy but now seems very floppy and irritable.','His family is of Ashkenazi Jewish descent.','His head is growing too fast, and he does not follow faces with his eyes.','Brain MRI shows widespread white matter changes, and MR spectroscopy shows a large NAA peak.','His urine has very high N-acetylaspartic acid, and genetic testing finds ASPA mutations.']::text[]),
(474,'Extreme',array['Neurology','Genetics']::text[],'Charcot-Marie-Tooth Disease','charcot-marie-tooth-disease','charcot-marie-tooth-disease',array['A 17-year-old boy visits the clinic because he keeps tripping and twisting his ankles.','He has been clumsy at sports since childhood and needs special shoes.','His father and grandmother had the same foot shape and problems walking.','He has high arches, hammer toes, and lifts his knees high when he walks.','His lower legs are very thin, like upside-down champagne bottles, and his ankle reflexes are absent.','Nerve tests show very slow conduction, and genetic testing shows a PMP22 gene duplication.']::text[]),
(475,'Extreme',array['Otolaryngology (ENT)','Pediatrics']::text[],'Choanal Atresia','choanal-atresia','choanal-atresia',array['A newborn girl turns blue and struggles to breathe shortly after birth.','The blue spells get better whenever she cries.','She also has a heart defect, small ears, and a coloboma in one eye.','She becomes blue again during feeding and when calm.','A thin feeding tube cannot be passed through either nostril into her throat.','CT shows a bony block at the back of both nasal passages; an oral airway is used until surgery.']::text[]),
(476,'Extreme',array['Endocrinology','Pediatrics']::text[],'Congenital Hypothyroidism','congenital-hypothyroidism','congenital-hypothyroidism',array['A 3-week-old baby boy is checked because he is very sleepy and hard to wake for feeds.','He is constipated and rarely cries.','He was born after 42 weeks and was a heavy baby; his newborn heel-prick result was missed.','He still has yellow skin, a large tongue, a hoarse cry, and a hernia at his belly button.','His front soft spot is very large, his skin is cold and mottled, and his muscle tone is low.','His TSH is very high and free T4 is low; he starts levothyroxine urgently to protect his brain development.']::text[]),
(477,'Extreme',array['Pediatrics','Surgery & Trauma']::text[],'Gastroschisis','gastroschisis','gastroschisis',array['A baby boy is born to a 19-year-old mother who smoked during pregnancy.','Her alpha-fetoprotein level was high at the second trimester screen.','Pregnancy scans showed free-floating bowel in the amniotic fluid.','At birth, loops of bowel are outside his tummy to the right of the umbilical cord.','The bowel is not covered by any sac and looks thick and swollen.','He is otherwise well formed, and the bowel is covered with a plastic silo and placed back gradually.']::text[]),
(478,'Extreme',array['Neurology','Genetics']::text[],'Friedreich Ataxia','friedreich-ataxia','friedreich-ataxia',array['A 12-year-old girl is brought to the clinic because she has become clumsy and unsteady over two years.','She falls more often, and her handwriting has become messy.','Her parents are healthy, but her older brother had similar problems.','She has slurred speech, absent ankle reflexes, loss of vibration sense, and upgoing toes.','She has a curved spine, high arches, and was recently diagnosed with diabetes.','Her echo shows a thick heart muscle, and genetic testing shows an expanded GAA repeat in the FXN gene.']::text[]),
(479,'Extreme',array['Hematology & Oncology','Immunology']::text[],'Hemophagocytic Lymphohistiocytosis (HLH)','hemophagocytic-lymphohistiocytosis','hemophagocytic-lymphohistiocytosis',array['A 30-year-old man is admitted with high fever that has lasted ten days despite antibiotics.','He had glandular fever a few weeks ago.','He has a rash, and he is getting more confused.','His liver and spleen are enlarged, and all three of his blood cell lines are low.','His ferritin is above 20,000 µg/L, his triglycerides are high, and his fibrinogen is low.','Bone marrow shows macrophages eating blood cells, soluble CD25 is very high, and he starts dexamethasone and etoposide.']::text[]),
(480,'Extreme',array['Metabolism','Genetics','Gastroenterology & Hepatology']::text[],'Lysosomal Acid Lipase Deficiency','lysosomal-acid-lipase-deficiency','lysosomal-acid-lipase-deficiency',array['A 10-year-old boy is referred because his liver enzymes have been high on several tests.','He is not overweight and does not take any medications.','His parents are cousins.','His liver is large and firm, and his spleen is also enlarged.','His LDL cholesterol is very high, and his HDL is low; liver biopsy shows fat in small droplets and orange-coloured tissue.','Dried blood spot testing shows very low acid lipase activity, and he starts sebelipase alfa.']::text[]),
(481,'Extreme',array['Gastroenterology & Hepatology','Infectious Diseases']::text[],'Whipple Disease','whipple-disease','whipple-disease',array['A 55-year-old white male farmer has had joint pain moving between large joints for years.','Over the past months he has had chronic diarrhoea and weight loss.','He has darker skin, swollen lymph nodes, and a low fever.','He has memory problems, and his eyes and jaw move together in a rhythmic way.','Small bowel biopsy shows widened villi filled with foamy macrophages that stain pink with PAS.','PCR confirms Tropheryma whipplei, and he starts IV ceftriaxone followed by a year of co-trimoxazole.']::text[]),
(482,'Extreme',array['Neurology','Neurosurgery']::text[],'Syringomyelia','syringomyelia','syringomyelia',array['A 32-year-old man visits his doctor about burns on his hands that he did not feel.','He has had a deep ache in his neck and shoulders for a few years.','He was told as a child that he had a malformation at the back of his skull.','He has lost pain and temperature feeling across his shoulders and arms in a cape shape, but touch is normal.','The small muscles of his hands are wasted, and his arm reflexes are absent while his legs are stiff.','MRI shows a fluid-filled cavity in the cervical spinal cord with a Chiari I malformation, and he has decompression surgery.']::text[]),
(483,'Extreme',array['Neurology']::text[],'Miller Fisher Syndrome','miller-fisher-syndrome','miller-fisher-syndrome',array['A 40-year-old man comes to the emergency department because he is seeing double.','He had a stomach bug with diarrhoea two weeks ago.','He does not have diabetes or high blood pressure.','He cannot move his eyes in several directions, and he walks very unsteadily.','All of his reflexes are absent, but the strength of his limbs is normal.','His spinal fluid has high protein with normal cells, and anti-GQ1b antibodies are positive; he improves with IVIG.']::text[]),
(484,'Extreme',array['Neurology','Infectious Diseases']::text[],'Creutzfeldt-Jakob Disease','creutzfeldt-jakob-disease','creutzfeldt-jakob-disease',array['A 62-year-old woman is brought to the clinic because she has become very forgetful over two months.','Her family says she is a different person, and she now needs help to dress.','She has no history of brain problems and is not taking any new medicines.','She has sudden jerks of her body when startled, and her walking is unsteady.','EEG shows periodic sharp wave complexes, and MRI shows bright ribbons in the cortex and basal ganglia.','Spinal fluid RT-QuIC is positive and 14-3-3 protein is raised; there is no cure, and supportive care is arranged.']::text[]),
(485,'Extreme',array['Hematology & Oncology','Genetics']::text[],'Hemophilia B (Christmas Disease)','hemophilia-b-christmas-disease','hemophilia-b',array['A 1-year-old boy bleeds for a long time after his circumcision.','He also gets large bruises from minor bumps.','His mother''s cousin had a bleeding disorder.','His platelet count and bleeding time are normal.','His PT is normal, but his APTT is prolonged and corrects in a mixing test, and factor VIII activity is normal.','Factor IX activity is 2%, and he is started on factor IX replacement.']::text[]),
(486,'Extreme',array['Endocrinology','Genetics']::text[],'Kallmann Syndrome','kallmann-syndrome','kallmann-syndrome',array['An 18-year-old man visits his doctor because he has not gone through puberty.','He has no facial hair, and his voice has not broken.','His uncle had a similar problem and needed fertility treatment.','He is tall with long arms, and his testes are small.','He has never been able to smell anything.','His LH, FSH, and testosterone are all low, and MRI shows missing olfactory bulbs; he starts hormone treatment.']::text[]),
(487,'Extreme',array['Genetics','Neurology','Pediatrics']::text[],'Krabbe Disease','krabbe-disease','krabbe-disease',array['A 4-month-old baby is brought in because she is extremely irritable and cries all the time.','She has become stiff and has stopped feeding well, with unexplained fevers.','Her parents are cousins.','She was developing normally at first but is now losing skills, and her vision seems poor.','She has stiff limbs, and her spinal fluid protein is high, and nerve conduction is slow.','Enzyme testing shows low galactocerebrosidase, and brain tissue would show globoid cells.']::text[]),
(488,'Extreme',array['Endocrinology','Obstetrics & Gynecology']::text[],'Sheehan Syndrome','sheehan-syndrome','sheehan-syndrome',array['A 30-year-old woman visits her doctor feeling exhausted three months after giving birth.','She has been unable to breastfeed because no milk came in.','Her delivery was complicated by heavy bleeding, and she needed several blood transfusions.','Her periods have not returned, and she feels cold and has lost hair in her armpits and pubic area.','Her blood pressure is low, her sodium is low, and her blood sugar drops easily.','Her cortisol, thyroid hormones, and prolactin are low, with low pituitary hormones, and MRI shows an empty sella.']::text[]),
(489,'Extreme',array['Infectious Diseases','Tropical Medicine']::text[],'Yellow Fever','yellow-fever','yellow-fever',array['A 30-year-old man comes to the clinic with a sudden high fever, headache, and back pain.','He returned five days ago from a trip to rural West Africa and did not get any travel vaccines.','He had many mosquito bites while camping near a forest.','His fever goes away for a day, then returns with yellow eyes, vomiting dark blood, and bleeding gums.','His heart rate is slow for his fever, his liver enzymes are extremely high, and his kidneys begin to fail.','PCR confirms a flavivirus spread by Aedes mosquitoes, and he receives intensive supportive care.']::text[]),
(490,'Extreme',array['Infectious Diseases']::text[],'Rocky Mountain Spotted Fever','rocky-mountain-spotted-fever','rocky-mountain-spotted-fever',array['A 9-year-old boy is brought to the clinic with a high fever and severe headache.','He has had muscle aches and vomiting for two days.','He returned from a summer camping trip in North Carolina a week ago.','A rash of small pink spots appears on his wrists and ankles and then spreads to his trunk.','The rash later involves his palms and soles and turns into tiny bleeding spots, and his sodium and platelets are low.','His parents remember removing a tick, and he starts doxycycline at once, as Rickettsia rickettsii is suspected.']::text[]),
(491,'Extreme',array['Nephrology & Urology','Vascular Surgery']::text[],'Renal Artery Dissection','renal-artery-dissection','renal-artery-dissection',array['A 42-year-old man comes to the emergency department with sudden severe pain in his left side.','The pain started while he was lifting weights at the gym.','He has no history of kidney stones.','His blood pressure is very high, and his urine shows a small amount of blood.','His LDH is markedly raised, but his creatinine is normal.','CT angiography shows a flap in the left renal artery with a wedge-shaped area of poor kidney blood flow.']::text[]),
(492,'Extreme',array['Infectious Diseases','Tropical Medicine']::text[],'Hookworm Infection','hookworm-infection','hookworm-infection',array['A 12-year-old boy who recently moved from a rural tropical area is brought in because he is tired and pale.','He has had a dry cough and wheezing a few weeks ago that went away on its own.','He used to walk barefoot on farmland.','He remembers an itchy red rash on his feet before the cough began.','His blood count shows iron deficiency anaemia and raised eosinophils.','Stool microscopy shows thin-shelled oval eggs, and he is treated with albendazole and iron.']::text[]),
(493,'Extreme',array['Nephrology & Urology','Genetics']::text[],'Horseshoe Kidney','horseshoe-kidney','horseshoe-kidney',array['A 25-year-old woman visits her doctor about repeated urinary tract infections.','She also has back pain when she bends backward.','She has short stature, a webbed neck, and was diagnosed with a chromosome problem as a child.','An ultrasound shows a kidney stone.','Both kidneys sit lower than normal and are angled inwards.','CT shows the lower poles of the kidneys joined in front of the aorta below the inferior mesenteric artery.']::text[]),
(494,'Extreme',array['Cardiology','Genetics']::text[],'Brugada Syndrome','brugada-syndrome','brugada-syndrome',array['A 35-year-old man is brought to the emergency department after passing out while asleep.','His wife heard him breathing strangely in his sleep, and he woke up confused.','His brother died suddenly at night at 40, and he is of South-East Asian descent.','He had a fever with flu the day before.','His ECG shows a coved ST elevation in leads V1 to V2 with a downward T wave.','Ajmaline makes the ECG pattern worse, testing shows an SCN5A mutation, and he has an ICD fitted.']::text[]),
(495,'Extreme',array['Cardiology','Genetics']::text[],'Arrhythmogenic Right Ventricular Cardiomyopathy (ARVC)','arrhythmogenic-right-ventricular-cardiomyopathy','arrhythmogenic-right-ventricular-cardiomyopathy',array['A 20-year-old footballer collapses during a match and recovers after a few seconds.','He has had palpitations during training for the past year.','His cousin died suddenly while jogging at 25.','His resting ECG shows negative T waves in leads V1 to V3 and a small notch after the QRS (epsilon wave).','Holter monitoring shows runs of ventricular tachycardia with a left bundle branch block shape.','Cardiac MRI shows a dilated right ventricle with fatty replacement of the muscle, and he has an ICD and stops competitive sport.']::text[]),
(496,'Extreme',array['Otolaryngology (ENT)']::text[],'Cholesteatoma','cholesteatoma','cholesteatoma',array['A 35-year-old man visits the ENT clinic about his left ear.','He has had a smelly discharge from that ear for months that keeps coming back despite drops.','He had many ear infections as a child and a hole in his eardrum.','His hearing in the left ear has slowly got worse.','Otoscopy shows white, pearly debris in the upper part of his eardrum.','CT shows erosion of the ossicles and nearby bone by a mass of skin cells, and he is booked for surgery.']::text[]),
(497,'Extreme',array['Otolaryngology (ENT)','Genetics']::text[],'Otosclerosis','otosclerosis','otosclerosis',array['A 30-year-old woman visits the ENT clinic because her hearing is getting worse in both ears.','She hears better in noisy places, like on a busy train.','Her mother wore hearing aids from her forties, and her hearing got worse during her pregnancy.','Her eardrums look normal, with a faint pink blush behind one of them.','Rinne test shows bone conduction louder than air conduction in both ears, and an audiogram shows a dip at 2,000 Hz.','Fixation of the stapes footplate is found, and she has a stapedotomy.']::text[]),
(498,'Extreme',array['Ophthalmology','Genetics']::text[],'Leber Hereditary Optic Neuropathy','leber-hereditary-optic-neuropathy','leber-hereditary-optic-neuropathy',array['A 22-year-old man visits the eye clinic because his right eye vision became blurry over a few weeks.','There is no pain when he moves his eye.','His maternal uncle went blind in his twenties, and he smokes and drinks heavily.','Two months later, his left eye is affected in the same way, with a central blind spot.','His optic discs look swollen with small twisted vessels that do not leak dye on angiography.','Genetic testing finds a mitochondrial m.11778G>A mutation in ND4, and he is offered idebenone.']::text[]),
(499,'Extreme',array['Ophthalmology','Hematology & Oncology','Pediatrics']::text[],'Retinoblastoma','retinoblastoma','retinoblastoma',array['A 1-year-old girl is brought to the clinic by her mother, who is worried about her eyes.','In flash photos, one of her eyes shows a white glow instead of the red eye.','Her father had an eye removed as a child.','Her left eye drifts outward.','Exam under anaesthesia shows a white mass on the retina in both eyes, with calcium on ultrasound.','Genetic testing shows an RB1 mutation, and she is treated with chemotherapy and focal therapy.']::text[]),
(500,'Extreme',array['Obstetrics & Gynecology']::text[],'Placenta Accreta Spectrum','placenta-accreta-spectrum','placenta-accreta-spectrum',array['A 36-year-old woman is having her fourth baby.','She has had three caesarean sections in the past.','A routine scan at 20 weeks shows that the placenta lies low over the old caesarean scar.','Further ultrasound shows irregular spaces inside the placenta and a thinned muscle layer of the womb.','MRI shows the placenta growing deep into the uterine wall towards the bladder.','A team plans a caesarean hysterectomy at 35 weeks, leaving the placenta in place, with blood ready.']::text[])
